function petBodyH(T, kind) {
  const sp = (typeof PET_ART !== 'undefined') ? (PET_ART[kind] || null) : null;
  const base = T * .40 * 3.75 * (typeof HERO_ART_SCALE === 'number' ? HERO_ART_SCALE : .81);
  return base * ((sp && sp.k) || 1);
}
