    const t0 = ctx.currentTime + (delay || 0);
    const g = ctx.createGain();
    g.gain.setValueAtTime(.0001, t0);
    g.gain.exponentialRampToValueAtTime(Math.max(.001, vol || .12), t0 + .025);
