  const SFX_MAP = {};
  [CORE_SFX, SKILL_SFX, CHARGE_SFX, HERO_SFX].forEach(function (m) {
    Object.keys(m).forEach(function (k) { SFX_MAP[k] = m[k]; });
  });

  /* ══════════════════════════════════════════════════════════════
     v5.85：六格可聽半徑
     大逃殺一場上百人，每個人都在放彈、踢彈、被打、倒下 —— 以前每一顆
     炸彈、每一次受傷都會直接打進玩家的耳朵，遠處的聲音跟眼前的一樣大。
     現在的規則只有一條：
       ① 有座標的發聲源 → 只有「離本地玩家 6 格（歐氏距離）以內」才播。
       ② 沒有座標的（介面點擊、過場、玩家自己身上的動作）→ 照舊播。
       ③ 幾支全場廣播型的（縮圈警報、核彈警報、勝負）→ 不受距離限制。
     座標怎麼傳進來：
       · sfx(name, x, y)                 直接給世界座標（px）
       · sndScope(x, y, fn) / sndSet()   實體更新時標記「現在是誰在發聲」
     ══════════════════════════════════════════════════════════════ */
  const SND_RADIUS_CELLS = 6;
  // 全場廣播：不套距離（縮圈／核彈警報／勝負／介面）
  const SND_GLOBAL = {
    click: 1, victory: 1, win: 1, lose: 1, finish: 1, finishLose: 1,
    count: 1, go: 1, nope: 1, levelup: 1, doorOpen: 1,
    nukeAlarm: 1, warn: 1, sd: 1     // 縮圈／突死／核彈：全場都要聽到的廣播
  };
  // 同一幀的重複音（十幾顆連鎖炸彈）只留第一顆 → 不吵，也不會糊成一團
  const SND_GAP = { explode: .018, hurt: .018, die: .022 };
  let sndEmit = null;            // { x, y }：目前正在發聲的實體（世界座標 px）
  const sndGapT = {};            // 同名音效上次播放的時間
  const sndStat = { played: 0, dropped: 0, lastDrop: '' };

  function sndMe() {
    try {
      const ps = Game && Game.players;
      if (!ps || !ps.length) return null;
      const me = ps[0];
      return (me && me.x != null && me.y != null) ? me : null;
    } catch (e) { return null; }
  }
  function sndTile() {
    try { return (Game && Game.T) || 40; } catch (e) { return 40; }
  }
  function sndHearable(x, y, cells) {
    const me = sndMe();
    if (!me) return true;                     // 還沒有玩家（選單／載入）→ 不擋
    const R = (cells || SND_RADIUS_CELLS) * sndTile();
    const dx = x - me.x, dy = y - me.y;
    return dx * dx + dy * dy <= R * R;
  }
  function sndSet(x, y) {
    sndEmit = (x == null || y == null) ? null : { x: x, y: y };
    return sndEmit;
  }
  function sndSave() { return sndEmit; }
  function sndRestore(v) { sndEmit = v || null; }
  function sndScope(x, y, fn) {
    const old = sndEmit;
    sndSet(x, y);
    try { return fn(); } finally { sndEmit = old; }
  }
  function sndGap(name) {
    const g = SND_GAP[name];
    if (!g) return false;
    const now = (typeof performance !== 'undefined' && performance.now)
      ? performance.now() : Date.now();
    if (sndGapT[name] && now - sndGapT[name] < g * 1000) return true;
    sndGapT[name] = now;
    return false;
  }
  function sndStats() { return { played: sndStat.played, dropped: sndStat.dropped, lastDrop: sndStat.lastDrop }; }
  function sndReset() {
    sndStat.played = 0; sndStat.dropped = 0; sndStat.lastDrop = ''; sndEmit = null;
    for (const k in sndGapT) delete sndGapT[k];
  }

  const sfx = function (name, sx, sy, cells) {
    if (!settings.sfx) return;
    /* v5.85：六格以外不播。座標優先用參數，其次用目前標記的發聲實體。 */
    if (!SND_GLOBAL[name]) {
      let ex = (sx == null) ? null : sx, ey = (sy == null) ? null : sy;
      if (ex == null && sndEmit) { ex = sndEmit.x; ey = sndEmit.y; }
      if (ex != null && ey != null) {
        if (!sndHearable(ex, ey, cells)) { sndStat.dropped++; sndStat.lastDrop = name; return; }
        if (sndGap(name)) { sndStat.dropped++; sndStat.lastDrop = name; return; }
      }
    }
    sndStat.played++;
    // v5.83：新／重製的音效先查表，命中就結束（下面 switch 保留舊行為相容）
    const S = SFX_MAP[name];
    if (S) { try { S(); } catch (eS) {} return; }
    switch (name) {
      case 'place': tone(220, .09, 'square', .15, 160); break;
      case 'kick': tone(500, .1, 'square', .14, 900); break;
      case 'punch': tone(300, .12, 'sawtooth', .16, 80); break;
      // v4.19：中高階怪發現你時的低吼（兩顆低音，聽起來就不爽）
      case 'anger': tone(150, .16, 'sawtooth', .15, 96); tone(112, .20, 'square', .09, 72, .08); break;
      case 'throw': tone(400, .14, 'square', .13, 780); break;
      case 'pick': tone(600, .08, 'square', .13, 900); break;
      case 'explode': boom(.5, .55); tone(90, .3, 'sawtooth', .25, 40); break;
      // v5.33：核彈三連音 —— 警報（5 秒、最後 1 秒慢慢消音）／下墜／落地
      case 'nukeAlarm': {
        if (!ensure()) break;
        const t0 = ctx.currentTime;
        const o = ctx.createOscillator(), gn = ctx.createGain();
        o.type = 'square';
        for (let i = 0; i < 4; i++) {
          const b0 = t0 + i * 1.25;
          o.frequency.setValueAtTime(430, b0);
          o.frequency.linearRampToValueAtTime(690, b0 + .58);
          o.frequency.linearRampToValueAtTime(430, b0 + 1.20);
        }
        gn.gain.setValueAtTime(.0001, t0);
        gn.gain.linearRampToValueAtTime(.16, t0 + .30);
        gn.gain.setValueAtTime(.16, t0 + 3.70);
        gn.gain.linearRampToValueAtTime(.0001, t0 + 5.00);   // 最後一秒慢慢消音
        o.connect(gn); gn.connect(sfxGain);
        o.start(t0); o.stop(t0 + 5.05);
        break;
      }
      case 'nukeFall': {
        if (!ensure()) break;
        const t0 = ctx.currentTime, dur = 2.0;
        const nn = Math.floor(ctx.sampleRate * dur);
        const buf = ctx.createBuffer(1, nn, ctx.sampleRate);
        const d0 = buf.getChannelData(0);
        for (let i = 0; i < nn; i++) d0[i] = (Math.random() * 2 - 1) * (.25 + .75 * (i / nn));
        const src = ctx.createBufferSource(); src.buffer = buf;
        const f2 = ctx.createBiquadFilter(); f2.type = 'bandpass'; f2.Q.value = 1.1;
        f2.frequency.setValueAtTime(2400, t0);
        f2.frequency.exponentialRampToValueAtTime(260, t0 + dur);
        const gn = ctx.createGain();
        gn.gain.setValueAtTime(.05, t0);
        gn.gain.linearRampToValueAtTime(.26, t0 + dur * .85);
        gn.gain.linearRampToValueAtTime(.001, t0 + dur);
        src.connect(f2); f2.connect(gn); gn.connect(sfxGain);
        src.start(t0);
        tone(1500, dur, 'sawtooth', .06, 170);
        break;
      }
      case 'nukeBoom':
        boom(1.9, .95);
        boom(.7, .75, .10);
        boom(.35, .55, .26);
        tone(52, 1.5, 'sine', .55, 22);
        tone(150, .8, 'sawtooth', .22, 34, .02);
        tone(2200, .5, 'sawtooth', .08, 220);
        break;
      case 'item': tone(660, .09, 'square', .16); tone(880, .12, 'square', .16, null, .07); break;
      // v5.35：金幣叮（兩聲往上，跟撿道具的 square 音分得開）
      case 'coin': tone(1180, .08, 'triangle', .15); tone(1560, .10, 'triangle', .13, null, .055); break;
      case 'hurt': tone(200, .22, 'sawtooth', .2, 70); break;
      case 'die': // 死亡叫聲：拔高→長哀號下滑（音量加大，不被爆炸蓋過）
        tone(520, .14, 'square', .34, 980);
        tone(980, .2, 'square', .32, 700, .13);
        tone(700, .34, 'square', .32, 95, .3);
        tone(990, .5, 'triangle', .2, 110, .13);
        break;
      case 'gloat': // v1.7：凶手開心大笑「哈−哈−哈哈哈」（接在死亡叫聲後面）
        tone(700, .10, 'square', .28, null, .90);
        tone(620, .10, 'square', .28, null, 1.04);
        tone(700, .10, 'square', .28, null, 1.18);
        tone(520, .26, 'square', .28, 300, 1.34);
        tone(392, .30, 'triangle', .16, 260, 1.36);
        break;
      case 'warp': tone(300, .16, 'sine', .18, 1200); break;
      case 'dash': tone(520, .11, 'triangle', .13, 1450); tone(180, .09, 'sine', .07, 90); break;
      case 'cast': tone(300, .18, 'sawtooth', .10, 620); break;
      case 'roll': tone(140, .22, 'square', .09, 70); break;
      case 'gust': tone(900, .20, 'sine', .10, 260); break;
      case 'curse': tone(240, .30, 'sawtooth', .11, 80); break;
      case 'heal': tone(660, .10, 'sine', .12, 990); tone(990, .14, 'sine', .10, 1320); break;
      // v4.87：鴕鳥跳躍（起跳的短促氣音 ＋ 落地的低頻悶響）
      case 'hop': tone(420, .10, 'sine', .16, 900); tone(700, .07, 'triangle', .1, 1200, .02); break;
      case 'land': boom(.22, .38); tone(110, .16, 'sawtooth', .18, 60); break;
      // v4.89：落地重擊 —— 比 land 厚很多（次低頻下潛＋兩層碎土＋高頻撕裂）
      case 'slam':
        boom(.40, .72);
        tone(62, .36, 'sine', .42, 26);
        tone(148, .14, 'square', .17, 52, .01);
        boom(.16, .34, .05);
        tone(1500, .12, 'sawtooth', .07, 260, .01);
        break;
      // v4.89：俯衝（先一聲短促下墜，再砸地）
      case 'dive': tone(680, .18, 'sine', .14, 150); break;
      // v4.89：升級風暴鴕鳥（電流上衝＋悶雷）
      case 'storm':
        tone(280, .14, 'sine', .20, 1500);
        tone(900, .22, 'triangle', .16, 1900, .07);
        boom(.32, .40, .16);
        break;
      case 'nope': tone(180, .10, 'square', .12, 120); break;
      case 'door': tone(520, .12, 'square', .15); tone(660, .12, 'square', .15, null, .1); tone(880, .2, 'square', .16, null, .2); break;
      // 出口開啟（清場）：上行琶音 + 亮片叮咚 + 低頻推力，跟一般過場音明顯不同
      case 'doorOpen':
        tone(523, .10, 'square', .22);
        tone(659, .10, 'square', .22, null, .09);
        tone(784, .10, 'square', .22, null, .18);
        tone(1047, .16, 'square', .24, null, .27);
        tone(1319, .30, 'triangle', .18, null, .36);
        tone(1568, .45, 'sine', .15, 2093, .30);
        tone(2093, .35, 'sine', .10, 2637, .52);
        boom(.28, .26);
        break;
      case 'click': tone(700, .05, 'square', .1); break;
      case 'win': [523, 659, 784, 1047].forEach(function (f, i) { tone(f, .16, 'square', .18, null, i * .12); }); break;
      case 'lose': [400, 320, 240, 160].forEach(function (f, i) { tone(f, .2, 'sawtooth', .18, null, i * .14); }); break;
      // 一場戰鬥結束的專屬特效音：勝方號角 + 亮片上升音 + 低頻衝擊
      case 'finish':
        boom(.4, .32);
        [523, 659, 784, 1047].forEach(function (f, i) { tone(f, .14, 'square', .2, null, i * .1); });
        tone(1047, .55, 'triangle', .2, 1319, .46);
        tone(1568, .6, 'sine', .12, 2349, .6);
        tone(1319, .28, 'square', .13, 2093, 1.05);
        tone(784, .34, 'square', .14, 523, 1.2);
        break;
      case 'finishLose':
        boom(.32, .28);
        [392, 330, 262].forEach(function (f, i) { tone(f, .22, 'triangle', .2, null, i * .15); });
        tone(196, .55, 'sawtooth', .12, 140, .46);
        break;
      case 'victory': // v3.8：完整的獲勝小旋律（約 2.6 秒）：上行號角 → 轉調 → 收尾長音
        [523, 523, 523, 659].forEach(function (f, i) { tone(f, .12, 'square', .22, null, i * .13); });
        [784, 659, 784, 1047].forEach(function (f, i) { tone(f, .13, 'square', .22, null, .62 + i * .13); });
        tone(784, .16, 'square', .2, null, 1.20);
        tone(880, .16, 'square', .2, null, 1.38);
        tone(988, .16, 'square', .2, null, 1.56);
        tone(1047, .5, 'square', .24, null, 1.78);
        tone(1319, .42, 'triangle', .18, null, 1.82);
        tone(1568, .5, 'sine', .13, 2093, 1.95);
        boom(.2, .18); boom(.14, .30);
        break;
      case 'count': tone(880, .1, 'square', .16); break;
      case 'go': tone(1320, .25, 'square', .2); break;
      case 'sd': tone(140, .3, 'sawtooth', .2, 60); boom(.25, .35); break;
      case 'crush': boom(.3, .4); break;
    }
  };

  // --- 音樂（16 分音符步進序列器） ---
  function midiFreq(n) { return 440 * Math.pow(2, (n - 69) / 12); }
  // ===== 長曲系統 =====
  // 旋律用「級數記譜」（1-7 = 大調音階，+/- 升降八度，0 = 休止），格式「級數:長度」。
  // 貝斯與和聲墊由和弦自動鋪 → 每首 64 小節，約 2～2.8 分鐘無縫循環。
  const SCALE_MAJ = [0, 2, 4, 5, 7, 9, 11];
  const CH_ROOT = { C: 0, D: 2, E: 4, F: 5, G: 7, A: 9, B: 11 };
  function chordTones(name) {
    const m = name.match(/^([A-G])(m?)$/);
    const r = 48 + CH_ROOT[m[1]];
    return m[2] === 'm' ? [r, r + 3, r + 7] : [r, r + 4, r + 7];
  }
  function degMidi(tok, base) {
    const m = tok.match(/^([0-7])([+-]?)$/);
    if (!m) return null;
    const d = parseInt(m[1], 10);
    if (!d) return null;
    const o = m[2] === '+' ? 12 : m[2] === '-' ? -12 : 0;
    return base + SCALE_MAJ[d - 1] + o;
  }
