/* 手把對應表 —— 說明頁與測試共用同一份，改一處兩邊都跟著改 */
const PAD_MAP = [
  ['左蘑菇頭／十字鍵', '選單：移動游標　遊戲中：移動角色（8 向）'],
  ['右蘑菇頭', '選單：上下左右捲動畫面　遊戲中：上下縮放視野'],
  ['A', '確認／選取　遊戲中：放炸彈（撿彈、丟彈也用它）'],
  ['B', '返回上一頁　遊戲中：暫停／繼續'],
  ['X', '遙控引爆（要有 📱 遙控器）'],
  ['Y', '坐騎招式（恐龍吐火，要有坐騎）'],
  ['LB／RB', '選單：上一個／下一個項目（一定選得到每一個）　遊戲中：RB 衝刺'],
  ['LT／RT', '遊戲中：縮小／放大畫面'],
  ['Start', '暫停／繼續']
];

// ---------- 角色外觀（原創：8 隻可愛的胖胖動物，對應選角圖的 8 隻） ----------
const CHARACTERS = [
  { id: 'rabbit', name: '兔兔BIBI', en: 'Rabbit', animal: 'rabbit', tag: '美貌的',     color: '#9ecbff', dark: '#5a8fd0' },
  { id: 'bear',   name: '小熊BOBO', en: 'Bear',   animal: 'bear',   tag: '非常有特色的', color: '#c98d5a', dark: '#8f5f33' },
  { id: 'dog',    name: '柴犬KIKI', en: 'Dog',    animal: 'dog',    tag: '有個性的',    color: '#f5b971', dark: '#c07f3a' },
  { id: 'cat',    name: '貓咪NANA', en: 'Cat',    animal: 'cat',    tag: '賤賤的',      color: '#b8aef0', dark: '#7d68c9' },
  { id: 'pig',    name: '豬豬MOMO', en: 'Pig',    animal: 'pig',    tag: '非常可愛的',   color: '#ffb3c7', dark: '#d97f9c' },
  { id: 'panda',  name: '熊貓ZUZU', en: 'Panda',  animal: 'panda',  tag: '膽小的',      color: '#f2f4f8', dark: '#3a4250' },
  { id: 'frog',   name: '青蛙GUGU', en: 'Frog',   animal: 'frog',   tag: '獨特的',      color: '#7ee08a', dark: '#3fae56' },
  { id: 'chick',  name: '小雞DODO', en: 'Chick',  animal: 'chick',  tag: '特別的',      color: '#ffd95e', dark: '#d9a916' }
];

// 動物耳朵（畫在頭圓之前 → 耳朵在頭後面）
function animalEars(g, c, x, ty, R) {
  switch (c.animal) {
    case 'rabbit':
      g.fillStyle = c.color;
      [-1, 1].forEach(function (s) {
        g.beginPath(); g.ellipse(x + s * R * .38, ty - R * 1.05, R * .18, R * .5, s * .18, 0, 6.283); g.fill();
      });
      g.fillStyle = 'rgba(255,140,170,.8)';
      [-1, 1].forEach(function (s) {
        g.beginPath(); g.ellipse(x + s * R * .38, ty - R * 1.0, R * .09, R * .32, s * .18, 0, 6.283); g.fill();
      });
      break;
    case 'bear':
      g.fillStyle = c.dark;
      [-1, 1].forEach(function (s) {
        g.beginPath(); g.arc(x + s * R * .62, ty - R * .72, R * .26, 0, 6.283); g.fill();
      });
      g.fillStyle = 'rgba(255,225,185,.6)';
      [-1, 1].forEach(function (s) {
        g.beginPath(); g.arc(x + s * R * .62, ty - R * .72, R * .13, 0, 6.283); g.fill();
      });
      break;
    case 'pig':
      g.fillStyle = c.dark;
      [-1, 1].forEach(function (s) {
        g.beginPath(); g.ellipse(x + s * R * .55, ty - R * .78, R * .2, R * .26, s * .5, 0, 6.283); g.fill();
      });
      break;
    case 'frog':
      g.fillStyle = c.color;
      [-1, 1].forEach(function (s) {
        g.beginPath(); g.arc(x + s * R * .45, ty - R * .88, R * .24, 0, 6.283); g.fill();
      });
      break;
    case 'cat':
      g.fillStyle = c.color;
      [-1, 1].forEach(function (s) {
        g.beginPath();
        g.moveTo(x + s * R * .3 - R * .22, ty - R * .72);
        g.lineTo(x + s * R * .55, ty - R * 1.28);
        g.lineTo(x + s * R * .3 + R * .3, ty - R * .62);
        g.closePath(); g.fill();
      });
      g.fillStyle = 'rgba(255,140,170,.75)';
      [-1, 1].forEach(function (s) {
        g.beginPath();
        g.moveTo(x + s * R * .36 - R * .06, ty - R * .84);
        g.lineTo(x + s * R * .48, ty - R * 1.1);
        g.lineTo(x + s * R * .36 + R * .1, ty - R * .78);
        g.closePath(); g.fill();
      });
      break;
    case 'panda':
      g.fillStyle = c.dark;
      [-1, 1].forEach(function (s) {
        g.beginPath(); g.arc(x + s * R * .62, ty - R * .72, R * .26, 0, 6.283); g.fill();
      });
      break;
    case 'dog':
      g.fillStyle = c.dark;
      [-1, 1].forEach(function (s) {
        g.beginPath(); g.ellipse(x + s * R * .88, ty - R * .05, R * .24, R * .46, s * .3, 0, 6.283); g.fill();
      });
      break;
    case 'chick':
      g.strokeStyle = c.dark; g.lineWidth = Math.max(1.5, R * .09); g.lineCap = 'round';
      g.beginPath(); g.moveTo(x, ty - R * .95);
      g.quadraticCurveTo(x + R * .12, ty - R * 1.28, x + R * .32, ty - R * 1.16);
      g.stroke(); g.lineWidth = 1;
      break;
  }
}
// 臉部特徵（畫在眼睛之前：熊貓眼罩、青蛙眼珠）
function animalFaceUnder(g, c, x, ty, R) {
  if (c.animal === 'panda') {
    g.fillStyle = c.dark;
    g.beginPath(); g.ellipse(x - R * .3, ty - R * .02, R * .25, R * .31, -.3, 0, 6.283); g.fill();
    g.beginPath(); g.ellipse(x + R * .3, ty - R * .02, R * .25, R * .31, .3, 0, 6.283); g.fill();
  }
  if (c.animal === 'frog') {
    g.fillStyle = '#fff';
    g.beginPath(); g.arc(x - R * .45, ty - R * .88, R * .15, 0, 6.283); g.fill();
    g.beginPath(); g.arc(x + R * .45, ty - R * .88, R * .15, 0, 6.283); g.fill();
    g.fillStyle = '#1b2430';
    g.beginPath(); g.arc(x - R * .45, ty - R * .88, R * .08, 0, 6.283); g.fill();
    g.beginPath(); g.arc(x + R * .45, ty - R * .88, R * .08, 0, 6.283); g.fill();
  }
}
// 臉部特徵（畫在眼睛之後：豬鼻、雞嘴、貓鬚、狗鼻）
