  if (!b || b.held || b.moving || b.flying) return false;
  // 剛放下不到 0.35 秒的炸彈不准撿 → 一路連放炸彈時不會把自己剛放的那顆撿起來
  if (b.owner === p && (b.age || 0) < .35) return false;
