  // v4.13：依路徑長度決定飛行時間 → 每格花的時間夠看清「一格一格跳」
  b.flying = { fx: bx, fy: by, tx: land.x, ty: land.y, t: 0,
    dur: Math.min(1.2, .10 + (path.length - 1) * .05), path: path };
  b.cx = land.x; b.cy = land.y;
