// 單人難易度設定（敵人數量／速度／魔王血量／恐龍蛋數量）
// v2.4：三種難度的 BOSS 統一 5 下（血條滿格 = 5，打五下就贏）
const BOSS_HITS = 5;
const SOLO_DIFF = {
  // v5.31：三檔都是 <b>3 條命</b>，差別在「每條命幾格血」與敵人強度；恐龍蛋一律 2 顆。
  //   lives＝命數、hp＝每條命幾格血（扣完才倒下）、hpInvuln＝掉一格之後的無敵秒數。
  easy:   { enemy: .62, speed: .80, bossHp: BOSS_HITS, eggs: 2, lives: 3, hp: 3, invuln: 3.4, hpInvuln: 1.8, label: '😇 簡單' },
  normal: { enemy: 1,   speed: 1,   bossHp: BOSS_HITS, eggs: 2, lives: 3, hp: 2, invuln: 2.2, hpInvuln: 1.8, label: '🙂 普通' },
  hard:   { enemy: 1.45, speed: 1.22, bossHp: BOSS_HITS, eggs: 2, lives: 3, hp: 1, invuln: 2.2, hpInvuln: 1.8, label: '😈 困難' }
};
function soloDiffCfg() {
  // v4.80：每日挑戰固定難度（不然排行榜就變成比誰調得簡單）
  if (Game.daily) return SOLO_DIFF[DAILY_DIFF] || SOLO_DIFF.normal;
  return SOLO_DIFF[settings.soloDiff] || SOLO_DIFF.normal;
}
/* v5.29：這一關要給幾格生命。
   每日挑戰（比秒數）與首頁「挑戰 BOSS」連戰固定 3 格 —— 排行榜要公平，
   不能因為玩家把難度調成簡單就多兩格；其餘照難度表走。 */
function soloLives() {
  if (Game.daily || Game.bossRush) return 3;
  const c = soloDiffCfg();
  const n = (c && c.lives) | 0;
  return n > 0 ? n : 3;
}
/* v5.30：這一關每一條命有幾格血。
   簡單＝2 格（被打到掉一格、第二下才倒下）；普通／困難＝1 格（維持原本的一擊倒）。
   每日挑戰與首頁 BOSS 連戰固定 1 格 —— 那兩個要比秒數／比分數，排行榜不能因為難度而不同。 */
function soloHpMax() {
  if (Game.rpg || Game.daily || Game.bossRush) return 1;
  const c = soloDiffCfg();
  const n = (c && c.hp) | 0;
  /* v5.38：血格每關都會重算，所以三選一的「生命 +1」加在這裡最安全
     —— 不會像其他屬性那樣被重複累加。每日挑戰不吃（公平）。 */
  const bonus = (Game.buffs && !Game.daily) ? (Game.buffs.hp | 0) : 0;
  return Math.max(1, (n > 0 ? n : 1) + bonus);
}
/* v5.30：掉一格血之後的無敵秒數 —— 要夠長，才不會站在同一團火裡被連扣兩格 */
function soloHpInvuln() {
  if (Game.rpg) return 1.15;
  const c = soloDiffCfg();
  return (c && c.hpInvuln) || 1.8;
}
/* v5.29：重生無敵秒數（簡單模式給比較久，暈一下也還有機會跑） */
function soloGuardInvuln() {
  if (Game.rpg || Game.daily || Game.bossRush) return 2.2;
  const c = soloDiffCfg();
  return (c && c.invuln) || 2.2;
}
// v4.77：難易度名稱跟著語言走（原本只有中文）
function diffLabel(id) {
  if (Game.daily) return t('daily.fixedDiff');
  const k = settings.soloDiff || 'normal';
  const v = t('diff.' + k);
  return (v && v !== 'diff.' + k) ? v : soloDiffCfg().label;
}
// 單人關卡時間（0 = 無限）
function soloTimeVal() {
  if (Game.daily) return DAILY_TIME;         // v4.80：每日挑戰固定 3 分鐘
  const t = parseInt(settings.soloTime, 10);
  return t > 0 ? t : 0;
}

// v4.63：王要站在「走得到」的格子。原本直接 Game.grid[by][bx] = 0 硬挖一格，如果那一格
//   四面都是岩層，挖出來就是一個「走不到、也炸不到」的死格 —— 王或小怪生在裡面就永遠打不到
//   （第 24 關就中了：章節最終關的中央底部那格正好被岩層包住）。
//   改成優先找一個現成的空地當站位：從底部往上、由中央往兩側找。
function pickBossCell(bx, by, cols, rows) {
  for (let yy = by; yy >= 1; yy--) {
    for (let d = 0; d < cols; d++) {
      const xs = d ? [bx - d, bx + d] : [bx];
      for (let i = 0; i < xs.length; i++) {
        const xx = xs[i];
        if (xx < 1 || xx > cols - 2) continue;
        if (Game.grid[yy][xx] !== 0) continue;
        if (Game.door && Game.door.x === xx && Game.door.y === yy) continue;   // 別坐在出口上
        return { x: xx, y: yy };
      }
    }
  }
  Game.grid[by][bx] = 0;                       // 整張圖都沒空地（不該發生）→ 照舊硬挖
  return { x: bx, y: by };
}

/* =====================================================================
   v4.80：每日挑戰 ＋ 排行榜
   ---------------------------------------------------------------------
   玩法：每天用「日期」算出一個種子 → 全世界當天長出同一張圖。
        規則固定（普通難度、3 分鐘、3 條命），所以能比：比通關秒數。
        同一天重開幾次都是同一張圖（種子只跟日期有關，不看時鐘）。
   排行榜：匿名（暱稱 + 秒數），後端 /api/lb/*，前端從 GitHub Pages 也能跨網域打。
        後端不在線時退回本機快取 —— 至少看得到自己的成績，不會變成一塊空白。
   ===================================================================== */
const DAILY_TIME = 180;          // 每日挑戰固定 3 分鐘
const DAILY_DIFF = 'normal';     // 固定普通難度（要公平就不能讓玩家自己調）

/* UTC+8 換日（跟後端 cloud.js 的 lbToday 一致；跨時區最多差一天，不影響同一天的人互相比） */
function dailyDayKey(d) {
  const t = d ? new Date(d) : new Date();
  const u = new Date(t.getTime() + 8 * 3600000);
  const p2 = function (n) { return (n < 10 ? '0' : '') + n; };
  return u.getUTCFullYear() + '-' + p2(u.getUTCMonth() + 1) + '-' + p2(u.getUTCDate());
}
/* 字串 → 32 位元種子（FNV-1a，夠散且完全確定） */
function dailySeedOf(day) {
  let h = 2166136261;
  const s = 'bh-daily-' + String(day || '');
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return (h >>> 0) | 0;
}
/* v5.39：40 關制下「一般關卡」共 32 關（每章第 5 關是 BOSS 決戰場）。
   0~31 對應到非 BOSS 的關號，維持「32 張地圖輪流」的原本手感。 */
function normalStageOf(k) {
  const i = ((k | 0) % 32 + 32) % 32;
  return Math.floor(i / 4) * BOSS_SLOT + (i % 4) + 1;
}
function dailyStageOf(seed) { return normalStageOf((seed >>> 7) >>> 0); }
function seedCodeOf(seed) {
  let c = (seed >>> 0).toString(36).toUpperCase();
  while (c.length < 5) c = '0' + c;
  return c.slice(-5);
}
/* 毫秒 → 3:24.7（排行榜用；小數一位，夠分勝負又不會太長） */
function fmtMs(ms) {
  const v = Math.max(0, Math.round(ms || 0));
  const m = Math.floor(v / 60000), s = Math.floor((v % 60000) / 1000), d = Math.floor((v % 1000) / 100);
  return m + ':' + (s < 10 ? '0' : '') + s + '.' + d;
}

const Daily = {
  KEY: 'bombhero-daily-best',
  MAX_KEEP: 30,
  /* 本機最佳紀錄：{ 'YYYY-MM-DD': ms } */
  all() {
    try {
      const o = JSON.parse(localStorage.getItem(Daily.KEY) || '{}');
      return (o && typeof o === 'object') ? o : {};
    } catch (e) { return {}; }
  },
  best(day) {
    const v = Daily.all()[day || dailyDayKey()];
    return (typeof v === 'number' && v > 0) ? v : 0;
  },
  saveBest(day, ms) {
    const o = Daily.all();
    if (!o[day] || ms < o[day]) o[day] = Math.round(ms);
    // 只留最近 30 天，免得 localStorage 愈長愈大
    const keys = Object.keys(o).sort();
    while (keys.length > Daily.MAX_KEEP) delete o[keys.shift()];
    try { localStorage.setItem(Daily.KEY, JSON.stringify(o)); } catch (e) {}
    return o[day];
  },
  today() { return dailyDayKey(); },
  seed() { return dailySeedOf(dailyDayKey()); },
  stage() { return dailyStageOf(dailySeedOf(dailyDayKey())); },
  /* ---- v5.11：每日挑戰獎金 --------------------------------------------
     以前過關只有名次，沒有實質回饋 → 「今天非玩不可」的理由不夠。
     規則（越簡單越好懂）：
       · 過關就發金幣：底薪 80 ＋ 速度獎金 0~220（3 分鐘用越快領越多）。
       · 當天只認「最高的一筆獎金」：破紀錄才補差額，重玩不會重複發。
       · 獎金紀錄存在本機，離線也記得（跟 Daily.best 一樣是本地資料）。 */
  PRIZE_KEY: 'bombhero-daily-prize',
  PRIZE_BASE: 80,
  PRIZE_SPEED: 220,
  prizes() {
    try {
      const o = JSON.parse(localStorage.getItem(Daily.PRIZE_KEY) || '{}');
      return (o && typeof o === 'object') ? o : {};
    } catch (e) { return {}; }
  },
  prizeOf(day) { return Daily.prizes()[day || dailyDayKey()] | 0; },
  /* 這個秒數值多少（不寫入，單純算） */
  prizePlan(ms) {
    const total = Math.max(1, DAILY_TIME * 1000);
    const left = Math.max(0, Math.min(total, total - Math.max(0, ms | 0)));
    const speed = Math.round((left / total) * Daily.PRIZE_SPEED / 5) * 5;
    return { base: Daily.PRIZE_BASE, speed: speed, total: Daily.PRIZE_BASE + speed };
  },
  /* 結算：回傳 { pay, total, full, best }，pay 是這次真正進錢包的金額 */
  award(day, ms) {
    const key = day || dailyDayKey();
    const plan = Daily.prizePlan(ms);
    const all = Daily.prizes();
    const got = all[key] | 0;
    const pay = Math.max(0, plan.total - got);
    if (pay > 0) {
      all[key] = plan.total;
      const keys = Object.keys(all).sort();
      while (keys.length > Daily.MAX_KEEP) delete all[keys.shift()];
      try { localStorage.setItem(Daily.PRIZE_KEY, JSON.stringify(all)); } catch (e) {}
      try { if (typeof Shop !== 'undefined' && Shop.addGold) Shop.addGold(pay); } catch (e) {}
    }
    return { pay: pay, total: Math.max(got, plan.total), plan: plan, before: got };
  },
  /* 開始今天的挑戰（規則固定，不讓玩家改難度／時間） */
  begin() {
    AudioSys.ensure(); AudioSys.sfx('click');
    ensureNickname();
    const day = Daily.today();
    const st = {
      day: day,
      seed: dailySeedOf(day),
      stage: dailyStageOf(dailySeedOf(day)),
      ms: 0,
      done: false,
      sent: false
    };
    /* v5.56：開場就去抓榜上殘影（到手就生效，不必等下一場） */
    try { Ghost.fetchRivals(); } catch (e3) {}
    try { startSolo(st.stage, false, st); } catch (e) {
      console.error('[daily]', e);
      try { toast('⚠️ ' + ((e && e.message) || e), 3.2); } catch (e2) {}
    }
  }
};

/* ---------------- 排行榜（前端） ---------------- */
const Lb = {
  TIMEOUT: 10000,         // 第一次連 Render 常卡在 DNS／TLS 握手（實測 7s+），給寬一點，失敗再重試一次
  last: null,             // { day, list, online, at }
  _busy: false,
  /* 後端位址：靜態空間（GitHub Pages／file://）沒有 /api，直接打 Render 那台 */
  origin() {
    let h = '', proto = '';
    try { h = location.hostname || ''; proto = location.protocol || ''; } catch (e) {}
    if (proto === 'file:') return 'https://bomb-hero-game.onrender.com';
    if (/^(localhost|127\.0\.0\.1|\[::1\]|0\.0\.0\.0)$/.test(h)) return '';
    if (/\.onrender\.com$/i.test(h)) return '';
    if (/\.github\.(io|com)$/i.test(h)) return 'https://bomb-hero-game.onrender.com';
    return '';
  },
  cacheKey(day) { return 'bombhero-lb-' + day; },
  readCache(day) {
    try {
      const o = JSON.parse(localStorage.getItem(Lb.cacheKey(day)) || 'null');
      return (o && o.list) ? o : null;
    } catch (e) { return null; }
  },
  writeCache(day, list) {
    try { localStorage.setItem(Lb.cacheKey(day), JSON.stringify({ at: Date.now(), list: list })); } catch (e) {}
  },
  /* v5.17：線上名單／排行榜「我是誰」。
     以前一律用 deviceId → 同一個帳號在手機＋電腦會變成兩個玩家（名單兩個同名、
     成就分一模一樣、排行榜各佔一格）。現在登入正式帳號就用帳號 id，
     遊客照舊用這台裝置；兩邊都不會互相蓋到。 */
  idKey() {
    try {
      // Cloud 對外叫 guest()（不是 isGuest），兩個都認，才不會把遊客誤判成會員
      const isGuest = (typeof Cloud === 'undefined') ? true
        : (typeof Cloud.guest === 'function' ? !!Cloud.guest()
          : (typeof Cloud.isGuest === 'function' ? !!Cloud.isGuest() : true));
      if (typeof Cloud !== 'undefined' && Cloud.online && Cloud.online() && !isGuest) {
        const a = Cloud.acc && Cloud.acc();
        if (a && a.id) return 'acc-' + String(a.id);
      }
    } catch (e) {}
    return Lb.deviceId();   // 遊客：原封不動回傳（改了會讓所有現有玩家的 pid 全部變號）
  },
  /* 這台裝置的匿名指紋：跟 Cloud 的遊客 id 共用，換裝置就是另一個人 */
  deviceId() {
    const K = 'bombhero-device';
    let id = '';
    try { id = localStorage.getItem(K) || ''; } catch (e) {}
    if (!id || id.length < 8) {
      id = 'dev-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
      try { localStorage.setItem(K, id); } catch (e) {}
    }
    return id;
  },
  /* 單次請求。第一次連後端常常卡在 DNS／TLS 握手（實測 7 秒以上才通），
     所以外層 _retry 會再打一次 —— 第二次連線已經暖了，通常 1 秒內回來。
     POST 重試是安全的：後端同裝置只升級不降級，重送同一個 ms 不會產生重複紀錄。 */
  _once(url, method, body) {
    return new Promise(function (resolve) {
      let done = false;
      const fin = function (v) { if (!done) { done = true; resolve(v); } };
      const ctl = (typeof AbortController !== 'undefined') ? new AbortController() : null;
      const tm = setTimeout(function () {
        try { if (ctl) ctl.abort(); } catch (e) {}
        fin({ ok: false, err: 'TIMEOUT' });
      }, Lb.TIMEOUT);
      const opt = { method: method, cache: 'no-store' };
      if (ctl) opt.signal = ctl.signal;
      if (body) { opt.headers = { 'Content-Type': 'application/json' }; opt.body = JSON.stringify(body); }
      fetch(url, opt).then(function (r) {
        return r.json().then(function (j) { fin(j || { ok: false }); }, function () { fin({ ok: false, err: 'BAD_JSON' }); });
      }).catch(function () { fin({ ok: false, err: 'NET' }); }).then(function () { clearTimeout(tm); });
    });
  },
  _retry(url, method, body) {
    return Lb._once(url, method, body).then(function (j) {
      if (j && (j.err === 'TIMEOUT' || j.err === 'NET')) return Lb._once(url, method, body);
      return j;
    });
  },
  _get(url) { return Lb._retry(url, 'GET', null); },
  _post(url, body) { return Lb._retry(url, 'POST', body || {}); },
  top(day) {
    const d = day || dailyDayKey();
    /* v5.56：ghosts=3 → 順便把前三名的殘影軌跡帶回來（約 3 KB），用來畫對手影子 */
    return Lb._get(Lb.origin() + '/api/lb/top?mode=daily&day=' + encodeURIComponent(d) + '&limit=50&ghosts=3')
      .then(function (j) {
        if (j && j.ok && j.list) {
          Lb.last = { day: d, list: j.list, online: true, at: Date.now() };
          Lb.writeCache(d, j.list);
        } else {
          const c = Lb.readCache(d);
          Lb.last = { day: d, list: (c && c.list) || [], online: false, at: Date.now() };
        }
        return Lb.last;
      });
  },
  submit(day, name, ms, path) {
    const body = {
      mode: 'daily', day: day, name: name || '', ms: Math.round(ms), deviceId: Lb.deviceId(),
      ver: VERSION
    };
    /* v5.56：附上殘影軌跡（後端只留前三名，其餘自動丟掉） */
    if (path) body.p = path;
    /* v5.56：順便帶上「我是誰」的展示資訊 —— 稱號代號＋配戴成就圖示 */
    try {
      body.tt = (typeof Ach !== 'undefined' && Ach.wornIdx) ? (Ach.wornIdx() | 0) : -1;
      const em = (typeof Ach !== 'undefined' && Ach.equippedMini) ? Ach.equippedMini() : [];
      let s = '';
      for (let i = 0; i < em.length && i < 3; i++) s += String(em[i].i || '');
      if (s) body.eq = s;
      body.pid = (typeof Social !== 'undefined' && Social.pid) ? Social.pid() : '';
    } catch (e0) { body.tt = -1; }
    return Lb._post(Lb.origin() + '/api/lb/submit', body);
  },
  /* v4.87：每週榜（同一個後端，換 mode／key）*/
  topWeek(week, limit) {
    const w = week || Gift.weekKey();
    const key = 'week:' + w;
    return Lb._get(Lb.origin() + '/api/lb/top?mode=weekly&day=' + encodeURIComponent(w) +
                   '&limit=' + (limit || 20))
      .then(function (j) {
        if (j && j.ok && j.list) { Lb.writeCache(key, j.list); return { list: j.list, online: true }; }
        const c = Lb.readCache(key);
        return { list: (c && c.list) || [], online: false };
      }, function () {
        const c = Lb.readCache(key);
        return { list: (c && c.list) || [], online: false };
      });
  },
  submitWeek(week, name, ms) {
    return Lb._post(Lb.origin() + '/api/lb/submit', {
      mode: 'weekly', day: week || Gift.weekKey(), name: name || '', ms: Math.round(ms),
      deviceId: Lb.deviceId(), ver: VERSION
    });
  },
  /* v5.73：深淵榜 —— 唯一「越大越好」的榜（ms 欄位存層數）。
     後端 day 固定 all（永久累計），比較方向也相反。 */
  topAbyss(limit) {
    return Lb._get(Lb.origin() + '/api/lb/top?mode=abyss&limit=' + (limit || 10))
      .then(function (j) {
        if (j && j.ok && j.list) { Lb.writeCache('abyss', j.list); return { list: j.list, online: true }; }
        const cc = Lb.readCache('abyss');
        return { list: (cc && cc.list) || [], online: false };
      }, function () {
        const cc = Lb.readCache('abyss');
        return { list: (cc && cc.list) || [], online: false };
      });
  },
  /* v5.73：本週限制挑戰（同週同一張圖＋同一條限制，比秒數） */
  topChal(week, limit) {
    const w = week || Gift.weekKey();
    return Lb._get(Lb.origin() + '/api/lb/top?mode=wchal&day=' + encodeURIComponent(w) +
                   '&limit=' + (limit || 20))
      .then(function (j) {
        if (j && j.ok && j.list) return { list: j.list, online: true };
        return { list: [], online: false };
      }, function () { return { list: [], online: false }; });
  },
  submitChal(week, name, ms) {
    return Lb._post(Lb.origin() + '/api/lb/submit', {
      mode: 'wchal', day: week || Gift.weekKey(), name: name || '', ms: Math.round(ms),
      deviceId: Lb.deviceId(), ver: VERSION
    });
  },
  submitAbyss(layer, name) {
    const n = Math.max(1, Math.round(layer || 1));
    return Lb._post(Lb.origin() + '/api/lb/submit', {
      mode: 'abyss', day: 'all', name: name || '', ms: n,
      deviceId: Lb.deviceId(), ver: VERSION
    });
  }
};

/* ============================================================================
   v5.73：本週限制挑戰（Weekly Challenge）
   · 每週一條限制（按週 key 固定）、同一張圖（Gift.weekStage()）比最快秒數
   · 與每日／每週榜完全分開（mode=wchal）—— 限制條件下的成績不能跟一般榜混在一起
   · 三條限制刻意都是「改玩法」而不是「加數值」：
       長引信 → 逼你算時機；無隨從 → 靠自己走位；無補給 → 不能靠回血硬撐
   ========================================================================== */
const WK_MODS = [
  { id: 'fuse',   ico: '\uD83D\uDD6F\uFE0F', key: 'wk.mod.fuse' },
  { id: 'nopet',  ico: '\uD83D\uDEAB', key: 'wk.mod.nopet' },
  { id: 'noitem', ico: '\uD83D\uDD12', key: 'wk.mod.noitem' }
];
const WeekChal = (function () {
  let cachedWk = '', cachedMod = null;
  function modOf() {
    const k = Gift.weekKey();
    if (k === cachedWk && cachedMod) return cachedMod;
    let h = 0;
    for (let i = 0; i < k.length; i++) h = (Math.imul(h, 131) + k.charCodeAt(i)) >>> 0;
    cachedWk = k; cachedMod = WK_MODS[h % WK_MODS.length];
    return cachedMod;
  }
  function stageOf() { return Gift.weekStage(); }
  function active() { return !!Game.wchal; }
  function bestKey() { return 'bombhero-wkchal-' + Gift.weekKey(); }
  function best() { try { return parseInt(localStorage.getItem(bestKey()), 10) || 0; } catch (e) { return 0; } }
  function setBest(ms) { try { localStorage.setItem(bestKey(), String(Math.round(ms) | 0)); } catch (e) {} }
  function begin() {
    const st = stageOf(), mod = modOf().id;
    Game.wchal = { mod: mod, at: Date.now() };
    startSolo(st, false, false);
    Game.wchal = { mod: mod, at: Date.now(), t0: Date.now() };
    const p = Game.players[0];
    if (p) {
      if (mod === 'fuse') p.fuseMul = Math.max(1.6, p.fuseMul || 1);
      if (mod === 'nopet') { Game.pets = []; p.wkNoPet = 1; }
      if (mod === 'noitem') { Game.items = []; p.wkNoItem = 1; }
    }
    try {
      doorHintCard(modOf().ico, t('wk.title'), t(modOf().key), 2.8);
    } catch (e) {}
  }
  /* 過關 → 提交；只收「本週指定關卡」且沒用每日挑戰 */
  function submit(p) {
    if (!active() || Game.daily) return;
    const used = Math.round((Game.timerMax - Game.timer) * 1000);
    if (!(used > 1000)) return;
    const bk = best();
    if (!bk || used < bk) {
      setBest(used);
      try { Ghost.finish(Gift.weekKey(), used); } catch (e) {}
      try {
        Lb.submitChal(Gift.weekKey(), settings.playerName || '', used).then(function (r) {
          if (r && r.ok && r.rank) toast(t('wk.rank', { r: r.rank, t: fmtMs(used) }), 3);
          else toast(t('wk.record', { t: fmtMs(used) }), 2.8);
        }, function () {});
      } catch (e) {}
    }
  }
  return { modOf: modOf, stageOf: stageOf, begin: begin, submit: submit, best: best, active: active, MODS: WK_MODS };
})();

/* =====================================================================
 * v5.13：成就系統（Ach）
 * ---------------------------------------------------------------------
 * 為什麼要自己一套計數器：
 *   · 遊戲裡本來只有「這一場的分數」，跨場次的累積（生涯殺幾隻、玩幾小時）
 *     全部沒有存。成就要看的是生涯，所以先建一份 counters 再往上長成就。
 *   · counters 是「只增不減」的整數，合併雲端存檔時取 max 就是正確的（不會被舊資料蓋掉）。
 *
 * 成就分（pts）：每一階給 (階級序 + 1) × 2 分 → 第一階 2 分、第九階 18 分。
 *   為什麼不直接算「數量」：使用者要的門檻是 10/50/75/100/250/500/750/1000，
 *   但全部成就只有 ~190 個，用「數量」永遠到不了 1000；用分數就合理了。
 *   分數累積到門檻 → 自動換頭上的稱號（顏色／外框／名字都不一樣）。
 * ================================================================== */
