  const foeD = isFoe ? Math.sqrt(tgtD2) / T : 99;
  // v5.67：這裡以前拿不到難度參數（硬寫 .6），現在自己抓一份（cfg 有快取，成本可忽略）
  const lv = BR_AI.cfg(aiLevelCfg(), Game.brZone ? Game.brZone.phase : 0);
  const eng = brEngageR(Game.brZone ? Game.brZone.phase : 0);
