  function passable(x, y) { return cellAt(x, y) === 0 && !bombAt(x, y); }
  function neighborOk(dn) { const d = DIRS[dn]; return passable(cx + d.x, cy + d.y); }
  p.aiT = (p.aiT || 0) - dt;
