    const py = oy + (((dhash(sd, 6, 141) * H + t * d.vy * sp) % H) + H) % H;
    const sz = (d.s[0] + dhash(sd, 3, 143) * (d.s[1] - d.s[0])) * T * .055;
    if (!isFinite(px) || !isFinite(py) || !isFinite(sz)) continue;
