      ctx.globalCompositeOperation = 'lighter';
      const hg = ctx.createRadialGradient(px, py, 0, px, py, sz * 2);
      hg.addColorStop(0, 'rgba(' + col + ',.24)');
      hg.addColorStop(1, 'rgba(' + col + ',0)');
