      ctx.beginPath(); ctx.ellipse(px, py, sz, sz * .52, .4, 0, TAU); ctx.stroke();
      ctx.beginPath(); ctx.ellipse(px + sz * 1.1, py + sz * .34, sz * .66, sz * .34, .4, 0, TAU); ctx.stroke();
