  woolWave:   [['a', 8.6, 12, 4.3, 3.1416, 6.2832], ['a', 17.2, 12, 4.3, 0, 3.1416], ['l', 2, 12, 4.4, 12], ['l', 21.4, 12, 23, 12]],
