  shadowRing: [['a', 12, 12, 8.8, 0, .95], ['a', 12, 12, 8.8, 1.62, 2.57], ['a', 12, 12, 8.8, 3.19, 4.14], ['a', 12, 12, 8.8, 4.76, 5.71], ['c', 12, 12, 2.4]]
