// 招式 → 圖示（王的 dive 沿用同一張）
function castIconKey(e) {
  const sk = e.castSkill || '';
  return CAST_ICONS[sk] ? sk : null;
}
/* v5.83：困難模式藏圖示 —— 只藏「頭頂圖示」，地面警示圈／雷射線照樣會亮，
   玩家少了「牠要出招了」的提示，但落點資訊還在（不是無跡可尋）。 */
function castIconOn() {
  try {
    if (Game.daily) return true;                       // 每日挑戰固定普通難度
    if (Game.mapTest) return true;
    return settings.soloDiff !== 'hard';
  } catch (e) { return true; }
}
// 圖示的顯示進度 0→1（0＝剛起手，1＝要打出來了）
function castIconProg(e) {
  if (!(e.castT > 0)) return -1;
  const mx = e.castMax || FOE_CAST_WINDUP;
  return clamp(1 - e.castT / mx, 0, 1);
}
function castIconPath(op, a) {
  switch (op) {
    case 'c':
      ctx.beginPath(); ctx.arc(a[1], a[2], a[3], 0, 6.2832); ctx.fill(); break;
    case 'C':
      ctx.beginPath(); ctx.arc(a[1], a[2], a[3], 0, 6.2832); ctx.stroke(); break;
    case 'l':
      ctx.beginPath(); ctx.moveTo(a[1], a[2]); ctx.lineTo(a[3], a[4]); ctx.stroke(); break;
    case 'z':
      ctx.beginPath(); ctx.moveTo(a[1], a[2]);
      for (let i = 3; i + 1 < a.length; i += 2) ctx.lineTo(a[i], a[i + 1]);
      ctx.stroke(); break;
    case 't':
      ctx.beginPath(); ctx.moveTo(a[1], a[2]); ctx.lineTo(a[3], a[4]); ctx.lineTo(a[5], a[6]);
      ctx.closePath(); ctx.stroke(); break;
    case 'a':
      ctx.beginPath(); ctx.arc(a[1], a[2], a[3], a[4], a[5]); ctx.stroke(); break;
    case 'r':
      ctx.beginPath(); ctx.rect(a[1], a[2], a[3], a[4]); ctx.stroke(); break;
    case 's': {                                     // 雪花（6 向）
      const cx = a[1], cy = a[2], r = a[3];
      for (let i = 0; i < 6; i++) {
        const an = i * 1.0472;
        ctx.beginPath();
        ctx.moveTo(cx, cy);
        ctx.lineTo(cx + Math.cos(an) * r, cy + Math.sin(an) * r);
        ctx.stroke();
      }
      break;
    }
    case 'k': {                                     // 閃電
      const x = a[1], y = a[2], len = a[3] || 12;
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x + len * .34, y + len * .40);
      ctx.lineTo(x + len * .10, y + len * .40);
      ctx.lineTo(x + len * .42, y + len);
      ctx.stroke();
      break;
    }
    case 'x': {                                     // 星芒（8 向爆裂）
      const cx = a[1], cy = a[2], r = a[3];
      for (let i = 0; i < 8; i++) {
        const an = i * .7854;
        const rr = i % 2 ? r * .52 : r;
        ctx.beginPath();
        ctx.moveTo(cx + Math.cos(an) * r * .22, cy + Math.sin(an) * r * .22);
        ctx.lineTo(cx + Math.cos(an) * rr, cy + Math.sin(an) * rr);
        ctx.stroke();
      }
      break;
    }
  }
}
/* 畫一枚徽章：底牌 ＋ 元素色描邊 ＋ 圖示 ＋ 進度環 ＋ 呼吸脈動 ＋ 指向小三角
   x,y＝徽章中心；size＝邊長；prog 0→1；boss 決定尺寸加成 */
function castBadgePath(h, r) {
  ctx.beginPath();
  if (ctx.roundRect) { ctx.roundRect(-h, -h, h * 2, h * 2, r); return; }
  ctx.moveTo(-h + r, -h);
  ctx.lineTo(h - r, -h); ctx.quadraticCurveTo(h, -h, h, -h + r);
  ctx.lineTo(h, h - r); ctx.quadraticCurveTo(h, h, h - r, h);
  ctx.lineTo(-h + r, h); ctx.quadraticCurveTo(-h, h, -h, h - r);
  ctx.lineTo(-h, -h + r); ctx.quadraticCurveTo(-h, -h, -h + r, -h);
}
function drawCastBadge(x, y, size, key, col, prog, boss, side) {
  const def = CAST_ICONS[key];
  if (!def) return;
  const gt = Game.gameT || 0;
  const pulse = 1 + Math.sin(gt * (9 + prog * 9)) * .045 + prog * .05;
  const h = size * .5 * pulse;
  const r = size * .22;
  ctx.save();
  ctx.translate(x, y);
  // 指向小三角（讓玩家知道這是「這隻」的提示）。掛在左右側時改成朝怪物指
  ctx.globalAlpha = .82;
  ctx.fillStyle = 'rgba(6,10,18,.80)';
  ctx.beginPath();
  if (side) {
    const ex = -side * (size * .5 * pulse - 1), tx = -side * size * .66 * pulse;
    ctx.moveTo(ex, -h * .26); ctx.lineTo(ex, h * .26); ctx.lineTo(tx, 0);
  } else {
    ctx.moveTo(-h * .26, size * .5 * pulse - 1);
    ctx.lineTo(h * .26, size * .5 * pulse - 1);
    ctx.lineTo(0, size * .66 * pulse);
  }
  ctx.closePath(); ctx.fill();
  // 外光暈（越接近出手越亮）
  const gg = ctx.createRadialGradient(0, 0, h * .2, 0, 0, h * 1.5);
  if (gg && gg.addColorStop) {
    gg.addColorStop(0, col);
    gg.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.globalAlpha = .16 + prog * .30;
    ctx.fillStyle = gg;
    ctx.beginPath(); ctx.arc(0, 0, h * 1.45, 0, 6.2832); ctx.fill();
  }
  // 底牌
  ctx.globalAlpha = .95;
  ctx.fillStyle = 'rgba(7,11,20,.92)';
  castBadgePath(h, r);
  ctx.fill();
  // 牌面：從底部往上透出元素色的蓄力光（越接近出手越亮，沒有硬邊）
  ctx.save();
  castBadgePath(h, r);
  ctx.clip();
  const lg = ctx.createLinearGradient(0, h, 0, -h * .25);
  if (lg && lg.addColorStop) {
    lg.addColorStop(0, col);
    lg.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.globalAlpha = .10 + clamp(prog, 0, 1) * .34;
    ctx.fillStyle = lg;
    ctx.fillRect(-h, -h, h * 2, h * 2);
  }
  ctx.restore();
  // 底部蓄力條：剩下的時間直接畫成一條會長滿的橫條
  const pw = clamp(prog, 0, 1);
  const bw = h * .72, bh = Math.max(1.6, size * .055);
  const by = h * .62;
  ctx.globalAlpha = .30;
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(-bw, by, bw * 2, bh);
  if (pw > .02) {
    ctx.globalAlpha = .95;
    ctx.fillStyle = col;
    ctx.fillRect(-bw, by, bw * 2 * pw, bh);
    ctx.globalAlpha = .85;
    ctx.fillStyle = 'rgba(255,255,255,.85)';
    ctx.fillRect(-bw, by, bw * 2 * pw, Math.max(1, bh * .34));
  }
  // 元素色描邊（boss 加粗）
  ctx.globalAlpha = .95;
  ctx.strokeStyle = col;
  ctx.lineWidth = Math.max(1.4, size * (boss ? .075 : .060));
  castBadgePath(h, r);
  ctx.stroke();
  // 圖示本體：0~24 的方格座標系，先置中再縮放
  const k = (h * 1.20) / 24;
  ctx.save();
  ctx.scale(k, k);
  ctx.translate(-12, -12);
  ctx.lineJoin = 'round'; ctx.lineCap = 'round';
  ctx.lineWidth = 2.5;
  ctx.strokeStyle = '#ffffff';
  ctx.fillStyle = 'rgba(255,255,255,.95)';
  ctx.shadowColor = 'rgba(0,0,0,.55)';
  ctx.shadowBlur = size * .10;
  for (let i = 0; i < def.length; i++) castIconPath(def[i][0], def[i]);
  ctx.restore();
  ctx.restore();
}
/* 掃全部敵人（含王）畫圖示。王的大一號、再多一圈元素色光環 */
function drawCastIcons(T) {
  const list = Game.enemies;
  if (!list || !list.length) return;
  if (!castIconOn()) return;
  ctx.save();
  for (let i = 0; i < list.length; i++) {
    const e = list[i];
    if (!e || e.dead) continue;
    if (!(e.castT > 0)) continue;
    const key = castIconKey(e);
    if (!key) continue;
    if (!onScreen(e.x, e.y, T * 1.6)) continue;
    const prog = castIconProg(e);
    const col = BOLT_COLOR[e.fx] || (e.castCol || '#ffd166');
    /* v5.83b：原本 T*.46 的徽章在手機上只有十幾像素，圖案會糊成一顆球。
       放大到 T*.70（王一號 T*.92），並夾在看得見的範圍內：
       貼著畫面邊緣的怪，圖示不會被切掉、也不會鑽到頂欄底下。 */
    const size = e.boss ? T * 1.12 : T * .95;
    const vx0 = _vrPx.x0 + size * .75, vx1 = _vrPx.x1 - size * .75;
    const vy0 = _vrPx.y0 + size * .62, vy1 = _vrPx.y1 - size * .62;
    // v5.83e：王的圖示原本用 e.r*2.5 往上抬，但王實際畫出來是 r*4.9 高 → 牌子會蓋在臉上。
    //   改成跟 drawEnemy 同一條算式反推「頭頂」（4.9*BS*AK 身高、腳在 r*1.45*AK）再往上讓開。
    const _bBS = e.sizeMul || 1, _bAK = tileArtK();
    const upH = e.boss ? e.r * 4.9 * _bBS * _bAK : enemyArtR(e) * 1.95;   // 中心 → 頭頂
    const halfW = e.boss ? e.r * 1.55 * _bAK : enemyArtR(e);
    let bx = clamp(e.x, vx0, vx1);
    let by = e.y - upH - size * .78;
    let side = 0;
    // 貼著畫面上緣（王關的頭頂常常頂到地圖上緣）時，硬往下夾會直接壓在臉上，
    //   掛到腳下又會蓋到站在前面的玩家 → 改成掛在左／右側，三角形朝怪物指。
    if (by < vy0) {
      side = (bx > (_vrPx.x0 + _vrPx.x1) * .5) ? 1 : -1;
      by = clamp(e.y - upH * .62, vy0, vy1);
      bx = clamp(e.x + side * (halfW + size * .62), vx0, vx1);
    }
    drawCastBadge(bx, by, size, key, col, prog, !!e.boss, side);
  }
  ctx.restore();
}
// ===== v4.40：小怪吐彈集氣特效 =====
//   地面層：落點預告（大圈往內縮 ＋ 四角括號 ＋ 十字準心 ＋ 從怪物連過去的瞄準虛線）
function drawFoeCastGround(T) {
  const list = Game.enemies;
  if (!list || !list.length) return;
  for (let i = 0; i < list.length; i++) {
    const e = list[i];
    if (!(e.castT > 0) || e.skill === 'blink') continue;   // v4.61：鑽地的沒有落點準心
    // v5.0b：BOSS 用 castT 當「集氣條」但沒有 castX/castY → tx/ty 會變 NaN，
    //   畫出一支飄在身上的白十字＋暖色光暈。王有自己的地面光環，這裡整隻跳過。
    if (e.boss || e.castX == null || e.castY == null) continue;
    // v5.27 修 bug：`blink / beam / pulse / chain / dive / hazard / roller / homing`
    //   這幾招也會把 castT 設成正數（只是「出手前的僵直」），但牠們從來不寫 castX/castY
    //   → 留在 0/0。以前只擋 castX == null，於是這些怪全部在「地圖左上角那一格」
    //   畫出落點圈，還拉出一條往左上角 45 度的瞄準虛線（玩家看到的「發招指向錯亂」）。
    //   只有吐元素彈真的會指定落點 → 其他招式一律不畫地面預告。
    if (e.skill !== 'spit') continue;
    if (!(e.castX > 0) || !(e.castY > 0) ||
        e.castX >= (Game.cols | 0) || e.castY >= (Game.rows | 0)) continue;
    const k = clamp(1 - e.castT / (e.castMax || FOE_CAST_WINDUP), 0, 1);   // 0 → 1
    const col = BOLT_COLOR[e.fx] || '#ffb347';
    const tx = e.castX * T + T / 2, ty = e.castY * T + T / 2 + T * .10;
    const gt = Game.gameT;
    ctx.save();
    // 1) 命中格：淡色填底（越接近越濃）
    ctx.globalAlpha = .10 + k * .22;
    ctx.fillStyle = col;
    ctx.beginPath(); ctx.arc(tx, ty, T * .46, 0, 6.283); ctx.fill();
    // 2) 外圈往內縮，最後貼住格子邊
    const r0 = T * (1.45 - k * 1.02);
    ctx.globalAlpha = .30 + k * .60;
    ctx.strokeStyle = col;
    ctx.lineWidth = Math.max(2, T * (.055 + k * .075));
    ctx.beginPath(); ctx.arc(tx, ty, r0, 0, 6.283); ctx.stroke();
    // 3) 圈上跑動的短弧（內圈）
    ctx.globalAlpha = .55 + k * .40;
    ctx.lineWidth = Math.max(1.6, T * .045);
    for (let j = 0; j < 4; j++) {
      const a = gt * 2.4 + j * 1.5708;
      ctx.beginPath(); ctx.arc(tx, ty, r0 * .74, a, a + .58); ctx.stroke();
    }
    // 4) 四角括號（越近越往內夾 → 像狙擊鏡）
    const br = T * (.30 + k * .19);
    ctx.globalAlpha = .65 + k * .35;
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = Math.max(1.8, T * .050);
    for (let sx = -1; sx <= 1; sx += 2) {
      for (let sy = -1; sy <= 1; sy += 2) {
        const bx = tx + sx * br, by = ty + sy * br, L = T * .15;
        ctx.beginPath();
        ctx.moveTo(bx, by - sy * L); ctx.lineTo(bx, by); ctx.lineTo(bx - sx * L, by);
        ctx.stroke();
      }
    }
    // 5) 十字準心
    ctx.globalAlpha = .50 + k * .45;
    ctx.strokeStyle = col;
    ctx.lineWidth = Math.max(1.4, T * .035);
    ctx.beginPath();
    ctx.moveTo(tx - br * .62, ty); ctx.lineTo(tx + br * .62, ty);
    ctx.moveTo(tx, ty - br * .62); ctx.lineTo(tx, ty + br * .62);
    ctx.stroke();
    // 6) 怪物 → 落點的瞄準虛線（越近越實）
    ctx.globalAlpha = .22 + k * .45;
    ctx.strokeStyle = col;
    ctx.lineWidth = Math.max(1.6, T * .045);
    try { ctx.setLineDash([T * .16, T * .12]); } catch (e1) {}
    ctx.beginPath(); ctx.moveTo(e.x, e.y - (e.r || 12) * .3); ctx.lineTo(tx, ty); ctx.stroke();
    try { ctx.setLineDash([]); } catch (e2) {}
    ctx.restore();
  }
}
//   上層：怪物身上聚起來的元素球（中心白熱 → 外圈元素色 ＋ 往內收的粒子 ＋ 星芒）
function drawFoeCastFx(T) {
  const list = Game.enemies;
  if (!list || !list.length) return;
  for (let i = 0; i < list.length; i++) {
    const e = list[i];
    if (!(e.castT > 0)) continue;
    // v5.0b：BOSS 也用 castT 集氣，但沒有 fx → 會退回橘色，在頭頂炸出一顆
    //   白星芒＋大暖光暈，看起來像雜訊。王自己會畫「地面光環＋全身脈動」，這裡跳過。
    if (e.boss) continue;
    // v5.27：只有「真的在集氣」的吐彈與鑽地才長元素球。beam／pulse／hazard 那幾招
    //   的 castT 只是出手僵直（0.45~0.55 秒），頭上冒一顆愈來愈大的元素球會騙人。
    if (e.skill !== 'spit' && e.skill !== 'blink') continue;
    // v5.83e：這隻已經有頭頂圖示了，舊的「集氣球」就不要再擠在旁邊
    //   （兩顆亮球疊在一起，反而看不出圖示在畫什麼）。困難模式沒有圖示 → 照畫。
    if (e.castSkill && castIconOn()) continue;
    const k = clamp(1 - e.castT / (e.castMax || FOE_CAST_WINDUP), 0, 1);
    const col = BOLT_COLOR[e.fx] || '#ffb347';
    const R = (e.r || T * .32) * (.95 + k * .42);        // 光球半徑（越來越大；不蓋住整隻怪）
    const ox = e.x + (e.dirName === 'left' ? -R * .55 : e.dirName === 'right' ? R * .55 : 0);
    const oy = e.y - R * .85 - Math.sin(Game.gameT * 18) * T * .02 * k;
    const gt = Game.gameT;
    ctx.save();
    // 外光暈
    const gg = ctx.createRadialGradient(ox, oy, R * .10, ox, oy, R * 2.0);
    gg.addColorStop(0, col);
    gg.addColorStop(.35, 'rgba(255,255,255,.0)');
    ctx.globalAlpha = .24 + k * .26;
    ctx.fillStyle = col;
    ctx.beginPath(); ctx.arc(ox, oy, R * 1.75, 0, 6.283); ctx.fill();
    // 球體
    ctx.globalAlpha = .85 + k * .15;
    const cg = ctx.createRadialGradient(ox - R * .3, oy - R * .35, R * .05, ox, oy, R);
    cg.addColorStop(0, '#ffffff');
    cg.addColorStop(.42, col);
    cg.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = cg;
    ctx.beginPath(); ctx.arc(ox, oy, R, 0, 6.283); ctx.fill();
    // 往中心收的粒子（4 顆，看得出來「在聚氣」）
    ctx.fillStyle = '#ffffff';
    for (let j = 0; j < 4; j++) {
      const ph = ((gt * 1.9 + j * .25) % 1);
      const rr = R * (2.3 - ph * 1.9);
      const a = j * 1.5708 + gt * 1.3;
      ctx.globalAlpha = .30 + ph * .65;
      ctx.beginPath();
      ctx.arc(ox + Math.cos(a) * rr, oy + Math.sin(a) * rr, Math.max(1, T * .035 * (1 - ph * .4)), 0, 6.283);
      ctx.fill();
    }
    // 星芒（十字拉長，越大越亮）
    ctx.globalAlpha = .40 + k * .55;
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = Math.max(1.2, T * .028);
    const sl = R * (1.5 + Math.sin(gt * 9) * .25);
    ctx.beginPath();
    ctx.moveTo(ox - sl, oy); ctx.lineTo(ox + sl, oy);
    ctx.moveTo(ox, oy - sl); ctx.lineTo(ox, oy + sl);
    ctx.stroke();
    ctx.restore();
  }
}

//   沒有貼圖時回傳 false，呼叫端會退回原本的「拆件骨架」畫法 → 不會開天窗
function bossArtKey() {
  const ch = (typeof blockOf === 'function') ? blockOf(Game.stage || 1) : 1;
  return 'b' + ch;
}
function drawBossSprite(e, x, footY, H, flash) {
  // v5.1b：王可以自帶美術（大逃殺的亂入王不是用當前關卡決定的）
  const key = (e && e.artKey) || bossArtKey();
  if (typeof BossArt === 'undefined' || !BossArt.has(key)) return false;
  const M = BOSS_ART[key];
  // v5.0b：依狀態挑幀（出招 > 跑動 > 站立）
  const fi = (e.castT > 0) ? 3 : (e.moving ? ((Math.floor((e.walkT || 0) * 7) % 2) ? 2 : 1) : 0);
  const im = BossArt.get(key, fi);
  const img = flash ? (BossArt.whiteOf(key) || im) : im;
  if (!img) return false;
  const W = H * (M.asp || 1);
  const face = DIRS[e.dirName] || DIRS.down;
  const side = face.x < 0 ? -1 : 1;
  const t = Game.gameT;
  const resp = Math.sin(t * 2.1) * .018;                      // 呼吸
  const bob = Math.abs(Math.sin(t * 2.6)) * H * .012;          // 上下浮
  const lean = face.x ? side * Math.sin((e.walkT || 0) * 8) * .035 : 0;   // 走路左右傾
  ctx.save();
  ctx.translate(x, footY - bob);
  ctx.rotate(lean);
  ctx.scale(side * (1 + resp * .5), 1 - resp);
  ctx.drawImage(img, -W / 2, -H, W, H);
  ctx.restore();
  return true;
}

// ====
//   v5.1b：BOSS 身上的「地區屬性元素特效」
//     每一區的王都帶著自己地盤的元素在身上繞：草原＝飄葉、沙漠＝飛沙、
//     冰雪＝雪花、熔岩＝火星、霓虹＝電弧、深海＝氣泡、天空＝氣流、魔界＝紫焰。
//     全部是程序繪製（不吃美術預算），兩層：layer 0 畫在角色後面（光暈＋光環＋粒子）、
//     layer 1 畫在前面（少量、半透明，讓粒子「繞過身體」）。
//   粒子位置一律用確定性種子（sin／i 的倍數），不用 Math.random，才不會每幀亂跳。
// ====
const BOSS_ELEM = {
  1: { k: 'leaf',   rgb: '126,224,122', rgb2: '232,255,196', spd: .34, n: 9, dot: 'rgba(60,140,70,' },
  2: { k: 'sand',   rgb: '255,214,140', rgb2: '255,246,214', spd: .30, n: 10, dot: 'rgba(150,106,54,' },
  3: { k: 'ice',    rgb: '160,232,255', rgb2: '255,255,255', spd: .28, n: 11, dot: 'rgba(70,150,190,' },
  4: { k: 'ember',  rgb: '255,168,74',  rgb2: '255,240,190', spd: .58, n: 11, dot: 'rgba(190,60,20,' },
  5: { k: 'spark',  rgb: '255,150,232', rgb2: '255,255,255', spd: .85, n: 9, dot: 'rgba(120,70,200,' },
  6: { k: 'bubble', rgb: '140,240,255', rgb2: '255,255,255', spd: .26, n: 10, dot: 'rgba(40,120,150,' },
  7: { k: 'gust',   rgb: '224,240,255', rgb2: '255,255,255', spd: .70, n: 8, dot: 'rgba(120,160,200,' },
  8: { k: 'flame',  rgb: '196,132,255', rgb2: '240,214,255', spd: .50, n: 10, dot: 'rgba(70,30,110,' }
};
function bossElemOf(e) {
  const blk = (e && e.brBlock) || ((typeof blockOf === 'function') ? blockOf(Game.stage || 1) : 1);
  return BOSS_ELEM[blk] || BOSS_ELEM[1];
}
function drawBossElemFx(e, x, footY, H, T, layer) {
  if (!(H > 0)) return;
  const C = bossElemOf(e);
  const t = Game.gameT || 0;
  const A = function (a) { return 'rgba(' + C.rgb + ',' + a.toFixed(3) + ')'; };
  const A2 = function (a) { return 'rgba(' + C.rgb2 + ',' + a.toFixed(3) + ')'; };
  const seedA = (e.x * .013 + e.y * .017);
  const T2 = T || 32;
  ctx.save();
  if (!layer) {
    /* 1) 身體外的元素光暈（橢圓、跟著呼吸） */
    const cy = footY - H * .50;
    const puls = .5 + .5 * Math.sin(t * 2.1 + seedA);
    try {
      const rg = ctx.createRadialGradient(x, cy, H * .03, x, cy, H * .70);
      rg.addColorStop(0, A(.30 + .10 * puls));
      rg.addColorStop(.45, A(.14 + .06 * puls));
      rg.addColorStop(1, A(0));
      ctx.fillStyle = rg;
      ctx.beginPath(); ctx.ellipse(x, cy, H * .58, H * .74, 0, 0, 6.283); ctx.fill();
    } catch (err) {}
    /* 2) 腳下光環 ＋ 腰間光環（兩圈反向呼吸，最容易被看見） */
    for (let r2 = 0; r2 < 2; r2++) {
      const rr = H * (r2 ? .30 : .44) * (1 + .055 * Math.sin(t * (r2 ? 3.1 : 2.3) + r2 + seedA));
      ctx.strokeStyle = A(r2 ? .26 : .18);
      ctx.lineWidth = Math.max(1.2, T2 * (r2 ? .030 : .022));
      ctx.beginPath();
      ctx.ellipse(x, footY - H * (r2 ? .46 : .05), rr, rr * .34, 0, 0, 6.283);
      ctx.stroke();
    }
    /* 3) 貼地的元素流光（跑動時像拖著自己的屬性） */
    ctx.strokeStyle = A(.13);
    ctx.lineWidth = Math.max(1, T2 * .045);
    ctx.beginPath();
    ctx.ellipse(x, footY + T2 * .02, H * .40, H * .13, 0, 0, 6.283);
    ctx.stroke();
    /* 3.5) 環繞身體的三顆元素光珠（帶拖尾）—— 最顯眼的一層，一眼看出這隻王帶什麼屬性 */
    for (let o = 0; o < 3; o++) {
      const spin = t * (.95 + o * .16) + o * 2.094 + seedA;
      for (let tr = 3; tr >= 0; tr--) {                        // tr=0 是光珠本體，其餘是拖尾
        const ang = spin - tr * .16;
        const orx = x + Math.cos(ang) * H * .62;
        const ory = footY - H * .46 + Math.sin(ang) * H * .17 + Math.sin(t * 2.4 + o) * H * .018;
        const fade = tr === 0 ? 1 : (.46 - tr * .11);
        const rr2 = H * (.034 + (o === 0 ? .010 : 0)) * (tr === 0 ? 1 : (1 - tr * .18));
        try {
          const og = ctx.createRadialGradient(orx, ory, 0, orx, ory, rr2 * 4.0);
          og.addColorStop(0, A2(.95 * fade));
          og.addColorStop(.28, A(.80 * fade));
          og.addColorStop(1, A(0));
          ctx.fillStyle = og;
          ctx.beginPath(); ctx.arc(orx, ory, rr2 * 4.0, 0, 6.283); ctx.fill();
        } catch (e1) {}
        if (tr === 0) {
          ctx.fillStyle = A2(.98);
          ctx.beginPath(); ctx.arc(orx, ory, rr2 * .70, 0, 6.283); ctx.fill();
        }
      }
    }
    /* 3.6) 身體中段的元素光環（清楚的一圈，不是模糊光暈） */
    for (let r3 = 0; r3 < 2; r3++) {
      const rw = H * (r3 ? .74 : .60) * (1 + .04 * Math.sin(t * 2.6 + r3));
      ctx.strokeStyle = A(r3 ? .16 : .34);
      ctx.lineWidth = Math.max(1.4, T2 * (r3 ? .020 : .045));
      ctx.beginPath();
      ctx.ellipse(x, footY - H * .48, rw, rw * .30, 0, 0, 6.283);
      ctx.stroke();
    }
  }
  /* 4) 上升的元素粒子（繞在身體外圍 → 不會被身軀整個蓋住） */
  if (layer) {
    // 前面的細光環 —— 前後各畫一次，湊成完整一圈（特效才有「包住王」的感覺）
    const rw = H * .64;
    ctx.strokeStyle = A(.24);
    ctx.lineWidth = Math.max(1.2, T2 * .024);
    ctx.beginPath();
    ctx.ellipse(x, footY - H * .48, rw, rw * .30, 0, 0, 6.283);
    ctx.stroke();
  }
  const n = layer ? Math.max(2, Math.round(C.n * .40)) : C.n;
  for (let i = 0; i < n; i++) {
    const base = layer ? 5 : 0;
    const ph = ((t * C.spd + (i + base) * .127 + seedA * .1) % 1);
    if (ph < 0) continue;
    const ang = i * 2.399 + seedA;
    const rad = H * (.34 + .48 * (((i * .37 + .11) % 1)));
    const wob = Math.sin(t * 1.9 + i * 1.7) * H * .035;
    const px = x + Math.cos(ang) * rad + wob;
    const py = footY - H * (.06 + ph * 1.12);
    const a = (.42 + .58 * Math.sin(ph * Math.PI)) * (layer ? .55 : 1);
    if (a <= .01) continue;
    ctx.globalAlpha = 1;
    switch (C.k) {
      case 'leaf':            // 草原：小葉片打著轉往上飄
        ctx.fillStyle = A(a * .85);
        ctx.beginPath();
        ctx.ellipse(px, py, H * .038, H * .015, ang + t * 1.3 + i, 0, 6.283);
        ctx.fill();
        break;
      case 'sand':            // 沙漠：細沙往側邊掃
        ctx.fillStyle = C.dot + (a * .7).toFixed(3) + ')';
        ctx.fillRect(px + Math.sin(t * 2.2 + i) * H * .05, py, H * .020, H * .014);
        ctx.fillStyle = A(a * .55);
        ctx.fillRect(px + H * .022, py - H * .012, H * .012, H * .010);
        break;
      case 'ice':             // 冰雪：四角雪花（菱形＋十字）；先描一圈深色再上亮色 → 淺色地板上也看得見
        const s1 = H * .046;
        for (let pass = 0; pass < 2; pass++) {
          ctx.strokeStyle = pass ? A(a * .95) : (C.dot + (a * .75).toFixed(3) + ')');
          ctx.lineWidth = Math.max(1, T2 * (pass ? .022 : .050));
          ctx.beginPath();
          ctx.moveTo(px, py - s1); ctx.lineTo(px + s1 * .55, py); ctx.lineTo(px, py + s1); ctx.lineTo(px - s1 * .55, py);
          ctx.closePath();
          ctx.moveTo(px - s1 * 1.15, py); ctx.lineTo(px + s1 * 1.15, py);
          ctx.moveTo(px - s1 * .55, py - s1 * .95); ctx.lineTo(px + s1 * .55, py + s1 * .95);
          ctx.moveTo(px + s1 * .55, py - s1 * .95); ctx.lineTo(px - s1 * .55, py + s1 * .95);
          ctx.stroke();
        }
        break;
      case 'ember':           // 熔岩：火星（外圈橘、中心白熱、帶短尾）
        ctx.fillStyle = A(a * .50);
        ctx.beginPath(); ctx.arc(px, py + H * .035, H * .042, 0, 6.283); ctx.fill();
        ctx.fillStyle = A(a);
        ctx.beginPath(); ctx.arc(px, py, H * .028, 0, 6.283); ctx.fill();
        ctx.fillStyle = A2(Math.min(1, a * 1.1));
        ctx.beginPath(); ctx.arc(px, py, H * .016, 0, 6.283); ctx.fill();
        break;
      case 'spark':           // 霓虹：會閃的電弧
        if (Math.sin(t * 34 + i * 2.1) < -.15) break;
        ctx.strokeStyle = A(a);
        ctx.lineWidth = Math.max(1, T2 * .026);
        const s2 = H * .045;
        ctx.beginPath();
        ctx.moveTo(px - s2, py - s2 * .5);
        ctx.lineTo(px, py + s2 * .35);
        ctx.lineTo(px + s2 * .35, py - s2 * .25);
        ctx.lineTo(px + s2, py + s2 * .6);
        ctx.stroke();
        ctx.strokeStyle = A2(a * .8);
        ctx.lineWidth = Math.max(1, T2 * .012);
        ctx.stroke();
        break;
      case 'bubble':          // 深海：氣泡上升（空心＋高光）
        ctx.strokeStyle = A(a * .9);
        ctx.lineWidth = Math.max(1, T2 * .020);
        const br = H * (.022 + .016 * ((i * .29) % 1));
        ctx.beginPath(); ctx.arc(px, py, br, 0, 6.283); ctx.stroke();
        ctx.fillStyle = A2(a * .55);
        ctx.beginPath(); ctx.arc(px - br * .35, py - br * .35, br * .28, 0, 6.283); ctx.fill();
        break;
      case 'gust':            // 天空：氣流弧線（同樣先描深色，白雲地板上才看得見）
        for (let pass = 0; pass < 2; pass++) {
          ctx.strokeStyle = pass ? A(a * .85) : (C.dot + (a * .7).toFixed(3) + ')');
          ctx.lineWidth = Math.max(1, T2 * (pass ? .020 : .046));
          ctx.beginPath();
          ctx.arc(px, py, H * .058, ang + t * 3.2, ang + t * 3.2 + 1.25);
          ctx.stroke();
        }
        break;
      default:                // 魔界：紫焰（水滴狀）
        ctx.fillStyle = A(a * .85);
        ctx.beginPath();
        ctx.moveTo(px, py - H * .055);
        ctx.quadraticCurveTo(px + H * .034, py - H * .012, px, py + H * .014);
        ctx.quadraticCurveTo(px - H * .034, py - H * .012, px, py - H * .055);
        ctx.fill();
        ctx.fillStyle = A2(a * .7);
        ctx.beginPath(); ctx.arc(px, py - H * .006, H * .010, 0, 6.283); ctx.fill();
        break;
    }
  }
  ctx.restore();
}

/* v5.38：BOSS 分階段破防的視覺
 *   護盾期：兩圈反向旋轉的六角晶盾（隨剩餘片數變淡）。
 *   破防期：紅色脈動光暈 ＋ 往內收的地面光環（越接近結束收得越緊）。
 *   全部程序繪製，不吃美術預算。 */
function drawBossPhaseFx(e, x, footY, H, T) {
  const A = arenaBossOf(e);
  if (!A || A.bossDead || !(H > 0)) return;
  const t = Game.gameT || 0;
  const cy = footY - H * .52;
  if (A.breakT > 0) {
    const k = A.breakMax ? (1 - A.breakT / A.breakMax) : 0;
    const puls = .62 + .38 * Math.sin(t * 9.5);
    try {
      const rg = ctx.createRadialGradient(x, cy, H * .05, x, cy, H * .68);
      rg.addColorStop(0, 'rgba(255,90,60,' + (.34 * puls).toFixed(3) + ')');
      rg.addColorStop(.55, 'rgba(255,150,40,' + (.16 * puls).toFixed(3) + ')');
      rg.addColorStop(1, 'rgba(255,90,60,0)');
      ctx.fillStyle = rg;
      ctx.beginPath(); ctx.ellipse(x, cy, H * .60, H * .70, 0, 0, 6.283); ctx.fill();
    } catch (er) {}
    ctx.strokeStyle = 'rgba(255,120,70,' + (.42 + .34 * puls).toFixed(3) + ')';
    ctx.lineWidth = Math.max(2, T * .08);
    const rr = H * (.34 + .32 * (1 - k));
    ctx.beginPath(); ctx.ellipse(x, footY - H * .04, rr, rr * .34, 0, 0, 6.283); ctx.stroke();
    ctx.lineWidth = 1;
    return;
  }
  if (A.shield > 0) {
    const left = A.shield / Math.max(1, A.shieldMax);
    const spin = t * .55;
    ctx.save();
    ctx.translate(x, cy);
    for (let s2 = 0; s2 < 2; s2++) {
      const R = H * (.50 + s2 * .07);
      ctx.strokeStyle = 'rgba(150,220,255,' + ((.18 + .24 * left) * (1 - s2 * .38)).toFixed(3) + ')';
      ctx.lineWidth = Math.max(1.3, T * (.030 - s2 * .009));
      ctx.beginPath();
      for (let i = 0; i <= 6; i++) {
        const a = spin * (s2 ? -1 : 1) + i * 1.0472;
        const px = Math.cos(a) * R, py = Math.sin(a) * R * .46;
        if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
      }
      ctx.stroke();
    }
    ctx.restore();
    ctx.lineWidth = 1;
  }
}

function drawEnemy(e, T) {
  const castK = (e.castT > 0) ? clamp(1 - e.castT / (e.castMax || FOE_CAST_WINDUP), 0, 1) : 0;
  const shk = castK > 0
    ? Math.sin(Game.gameT * (54 + castK * 46) + e.x * .07) * T * (.020 + castK * .052)
    : 0;
  const shkY = castK > 0 ? Math.sin(Game.gameT * 41 + e.y * .05) * T * .016 * castK : 0;
  const x = e.x + shk, y = e.y + shkY;
  // v5.21：白閃改用獨立的 flashT（0.13 秒）—— 以前借用 hitT（0.55 秒無敵時間），
  //   結果怪物被打之後會白整整半秒，看起來像貼圖壞掉
  const flash = (e.flashT > 0) || (e.hitT > .42);
  // 飛行怪：影子在正下方地面、隨高度變淡
  // v2.4：小怪外型放大 → 影子跟著放大
  const ar = enemyArtR(e);
  if (e.kind === 'fly') {
    softShadow(x, y + ar * 1.15, ar * .62, ar * .2, .22);
  } else {
    // v1.8：BOSS 放大 → 影子也等比放大，才有壓迫感
    const sr = e.boss ? e.r * (e.sizeMul || 1) * tileArtK() : ar;   // v2.6：BOSS 影子跟著格子縮放
    softShadow(x, y + sr * .9, sr * .78, sr * .28, .36);
  }
  const wob = Math.sin(Game.gameT * 6 + x * .13) * 2;
  if (e.boss) {
    // 老虎國王 BOSS：用使用者提供的插畫（拆成頭／手／腳，走路會擺、會點頭）
    // v1.8：整個身軀放大（腳的位置不變 → 往上長高，看起來比玩家大一號）
    const BS = e.sizeMul || 1;
    const AK = tileArtK();                       // v2.6：BOSS 身軀跟著格子縮放
    const BH = e.r * 4.9 * BS * AK;
    const bFoot = y + e.r * 1.45 * (BS > 1 ? 1.08 : 1) * AK;
    const dir = DIRS[e.dirName] ? e.dirName : (e.vx < 0 ? 'left' : e.vx > 0 ? 'right' : 'down');
    // v5.1b：地區屬性元素特效（下層：光暈／光環／粒子）
    try { drawBossElemFx(e, x, bFoot, BH, T, 0); } catch (er) {}
    // v5.0b：集氣徵兆 —— 腳下一圈往內收的光環（顏色＝這隻王的屬性色）
    if (e.castT > 0) {
      const ck = 1 - e.castT / (e.castMax || .9);
      const col = e.castCol || '#fff';
      ctx.save();
      ctx.globalAlpha = .30 + .50 * ck;
      ctx.strokeStyle = col;
      ctx.lineWidth = Math.max(2, T * .075);
      const rr = e.r * (2.0 - ck * .75) * AK;
      ctx.beginPath();
      ctx.ellipse(x, y + e.r * 1.05 * AK, rr, rr * .40, 0, 0, 6.283);
      ctx.stroke();
      ctx.globalAlpha = .18 + .22 * ck;
      ctx.fillStyle = col;
      ctx.beginPath();
      ctx.ellipse(x, y + e.r * 1.05 * AK, rr * .92, rr * .36, 0, 0, 6.283);
      ctx.fill();
      ctx.restore();
      ctx.lineWidth = 1;
    }
    const drewBoss = drawBossSprite(e, x, bFoot, BH, flash);
    const rig = drewBoss ? true : drawRigChar(ctx, 'boss', x, bFoot, BH, {
      walk: (e.walkT || 0) * 9, moving: true, facing: dir,
      amp: .95, idle: Game.gameT, expr: flash ? 'hurt' : '',
      armSwing: .16, headTilt: Math.sin((e.walkT || 0) * 3) * .03
    });
    if (!rig) {
      // 插畫還沒載入 → 先畫外星魔王（不會開天窗）
      const R = e.r * 1.05 * tileArtK();
      ctx.strokeStyle = flash ? '#fff' : '#5e1a86';
      ctx.lineWidth = 3; ctx.lineCap = 'round';
      [-1, 1].forEach(function (s) {
        ctx.beginPath();
        ctx.moveTo(x + s * R * .35, y - R * .85);
        ctx.quadraticCurveTo(x + s * R * .7, y - R * 1.45, x + s * R * .4, y - R * 1.6 + wob * s);
        ctx.stroke();
      });
      ctx.lineWidth = 1;
      ctx.fillStyle = flash ? '#ffffff' : '#8a3fd0';
      ctx.beginPath(); ctx.ellipse(x, y - R * .15, R, R * 1.02, 0, 0, 6.283); ctx.fill();
      ctx.fillStyle = 'rgba(255,255,255,.18)';
      ctx.beginPath(); ctx.ellipse(x - R * .35, y - R * .6, R * .34, R * .18, -.5, 0, 6.283); ctx.fill();
      ctx.fillStyle = '#141826';
      ctx.beginPath(); ctx.ellipse(x - R * .34, y - R * .1, R * .2, R * .34, -.4, 0, 6.283); ctx.fill();
      ctx.beginPath(); ctx.ellipse(x + R * .34, y - R * .1, R * .2, R * .34, .4, 0, 6.283); ctx.fill();
      ctx.fillStyle = '#fff';
      ctx.beginPath(); ctx.arc(x - R * .4, y - R * .22, R * .06, 0, 6.283); ctx.fill();
      ctx.beginPath(); ctx.arc(x + R * .28, y - R * .22, R * .06, 0, 6.283); ctx.fill();
      ctx.fillStyle = '#5e1a86';
      ctx.beginPath(); ctx.ellipse(x, y + R * .45, R * .12, R * .08, 0, 0, 6.283); ctx.fill();
    }
    // v5.1b：上層的少量粒子（從身體前面繞過去，特效才有「包住」的感覺）
    try { drawBossElemFx(e, x, bFoot, BH, T, 1); } catch (er) {}
    try { drawBossPhaseFx(e, x, bFoot, BH, T); } catch (er) {}   // v5.38：護盾／破防
    // 血條（跟著老虎的高度走）
    //   v4.76：大逃殺的 BOSS 美術上下留白比較多 → 血條用身體高度算會飄在半空中，另外給一組係數
    const barY = e.brBoss ? (y - BH * .60 - 8) : (bFoot - BH - Game.T * .10);
    const bw = Math.max(52, Game.T * (e.brBoss ? 1.55 : 1.15));   // v1.8：BOSS 變大 → 血條也加寬
    ctx.fillStyle = 'rgba(0,0,0,.5)';
    ctx.fillRect(x - bw / 2, barY, bw, 7);
    ctx.fillStyle = '#ff5e6e';
    ctx.fillRect(x - bw / 2 + 1, barY + 1, (bw - 2) * (e.hp / e.maxHp), 5);
    /* v5.38：血條下面一排小方塊 = 剩餘護盾片數；
       破防時改成一條往左縮的黃條 ＋ 倍率字樣。 */
    const A3 = (Game.bossArena && Game.bossArena.boss === e) ? Game.bossArena : null;
    if (A3 && !e.brBoss) {
      ctx.save();
      if (A3.breakT > 0) {
        const kk = A3.breakMax ? (A3.breakT / A3.breakMax) : 0;
        ctx.fillStyle = 'rgba(0,0,0,.55)';
        ctx.fillRect(x - bw / 2, barY + 9, bw, 4);
        ctx.fillStyle = '#ffd166';
        ctx.fillRect(x - bw / 2, barY + 9, bw * kk, 4);
        ctx.font = '900 ' + Math.round(Game.T * .26) + 'px sans-serif';
        ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
        ctx.lineWidth = Math.max(2, Game.T * .06); ctx.strokeStyle = 'rgba(20,8,4,.9)';
        ctx.strokeText('×2', x + bw / 2 + 3, barY + 11);
        ctx.fillStyle = '#ffd166';
        ctx.fillText('×2', x + bw / 2 + 3, barY + 11);
        ctx.lineWidth = 1;
      } else if (A3.shield > 0) {
        const n = A3.shieldMax || 1, pw = (bw - (n - 1) * 2) / n;
        for (let i = 0; i < n; i++) {
          const on = i < A3.shield;
          ctx.fillStyle = on ? '#7fd4ff' : 'rgba(255,255,255,.14)';
          ctx.fillRect(x - bw / 2 + i * (pw + 2), barY + 9, pw, 3);
        }
      }
      ctx.restore();
    }
    // 王冠標記（大逃殺的亂入 BOSS 順便標是第幾關來的）
    ctx.font = '700 ' + Math.round(Game.T * (e.brBoss ? .28 : .34)) + 'px sans-serif';
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    if (e.brBoss) {
      // v5.1b：直接寫這隻新王的名字（顏色＝牠的屬性色），比「第 N 關亂入」好認
      const blk = e.brBlock || ((typeof blockOf === 'function') ? blockOf(e.brStage || 1) : 1);
      const nk = 'boss.' + blk;
      const nm = (typeof t === 'function') ? t(nk) : '';
      const lab = (nm && nm !== nk) ? nm : t('br.bossStage', { n: e.brStage || 1 });
      ctx.lineWidth = 2.6; ctx.strokeStyle = 'rgba(22,6,26,.92)';
      ctx.strokeText(lab, x, barY - Game.T * .24);
      ctx.fillStyle = ((typeof BOSS_KIT !== 'undefined' && BOSS_KIT[blk]) || {}).col || '#ffd9f2';
      ctx.fillText(lab, x, barY - Game.T * .24);
      ctx.lineWidth = 1;
    } else {
      // v5.0b：血條上方直接寫「這隻王叫什麼」—— 八隻各有名字與性格
      const bi = (typeof blockOf === 'function') ? blockOf(Game.stage || 1) : 1;
      const nk = 'boss.' + bi;
      const nm = (typeof t === 'function') ? t(nk) : '';
      if (nm && nm !== nk) {
        ctx.font = '900 ' + Math.round(Game.T * .26) + 'px "Microsoft JhengHei", sans-serif';
        ctx.lineWidth = Math.max(2, Game.T * .07); ctx.strokeStyle = 'rgba(16,10,24,.9)';
        ctx.strokeText(nm, x, barY - Game.T * .26);
        ctx.fillStyle = (bossKitOf(Game.stage) || {}).col || '#ffd9f2';
        ctx.fillText(nm, x, barY - Game.T * .26);
        ctx.lineWidth = 1;
      }
      // 集氣時頭上給一個圖示：💥＝要閃、⚡＝可以打斷
      if (e.castT > 0) {
        const interruptible = (e.castSkill === 'graze' || e.castSkill === 'iceShell');
        ctx.font = '700 ' + Math.round(Game.T * .34) + 'px sans-serif';
        const bob2 = Math.sin(Game.gameT * 12) * Game.T * .04;
        ctx.fillText(interruptible ? '⚡' : '💥', x + bw * .78, barY - Game.T * .30 + bob2);
      }
    }
    ctx.textAlign = 'start'; ctx.textBaseline = 'alphabetic';
    if (e.dizzy > 0) drawDizzyMark(x, barY - Game.T * .46, T);   // v1.9：BOSS 也會暈
    // v4.19：BOSS 被惹到也會冒出生氣泡泡（在血條右上方，不會壓到血條）
    if (e.aggro) drawAngerMark(x + bw * .74, barY - Game.T * .06, T, e.angerT);
    return;
  }
  // ---------- 10 種小怪的外型（有翅膀的飛、沒翅膀的走） ----------
  if (e.blinkT > 0) {
    ctx.fillStyle = 'rgba(160,140,220,.28)';
    ctx.beginPath(); ctx.ellipse(x, y + ar * .5, ar * .5, ar * .16, 0, 0, 6.283); ctx.fill();
    return;
  }
  drawFoeElement(e, x, y, ar, flash, 'back');
  drawEnemyArt(e, x, y, flash, wob);
  drawFoeElement(e, x, y, ar, flash, 'front');
  // v4.19：中階／高階小怪在 2 格內會一直冒「😡」＋怒氣泡泡（偏右上，不會蓋住頭暈）
  if (e.aggro && isAngryFoe(e)) drawAngerMark(x + ar * .72, y - ar * 1.42, T, e.angerT);
  if (e.dizzy > 0) drawDizzyMark(x, y - ar * 1.15, T);           // v1.9：頭暈（v2.4：跟著體型上移）
}

// ====
//   v4.27：新小怪的「參數化」繪製
//   48 隻不可能每隻手繪 30 行（那要 1,400 行），所以拆成 15 種身體原型 ＋ 配色 ＋
//   配件（耳朵／角／翅膀／殼／尾巴／護甲／發光）。每隻只要在 ENEMY_SPECIES 宣告
//   art: 'xxx'，就會長成那個樣子 —— 輪廓差異大、遠看也分得出來。
// ====
function drawFoeArchetype(sp, x, y, R, col, dk, flash, kit) {
  const art = (sp && sp.art) || 'blob';
  const t = kit.t || 0, look = kit.look || 1, step = kit.step || 0;
  const fly = !!kit.fly;
  const w = kit.w || 0;
  const Y = y + (fly ? Math.sin(t * 3 + (sp.spd || 40) * .07) * R * .12 : 0);
  const glow = sp.glow && !flash;

  // 共用：眼睛（黑底＋高光；發光怪用亮瞳）
  function eyes(dx, dy, rx, ry, pupil) {
    ctx.fillStyle = flash ? '#fff' : '#141826';
    ctx.beginPath(); ctx.ellipse(x - rx * 1.25 + dx, Y + dy, rx, ry, 0, 0, 6.283); ctx.fill();
    ctx.beginPath(); ctx.ellipse(x + rx * 1.25 + dx, Y + dy, rx, ry, 0, 0, 6.283); ctx.fill();
    if (!flash) {
      ctx.fillStyle = pupil || '#fff';
      ctx.beginPath(); ctx.arc(x - rx * 1.45 + dx, Y + dy - ry * .34, rx * .32, 0, 6.283); ctx.fill();
      ctx.beginPath(); ctx.arc(x + rx * 1.05 + dx, Y + dy - ry * .34, rx * .32, 0, 6.283); ctx.fill();
    }
  }
  // 共用：頭上的光暈（熔岩／霓虹／風精靈）
  function halo(rad, color) {
    if (flash || !ctx.createRadialGradient) return;
    let g = null;
    try { g = ctx.createRadialGradient(x, Y, rad * .2, x, Y, rad); } catch (e) { return; }
    if (!g || !g.addColorStop) return;
    g.addColorStop(0, color); g.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = g;
    ctx.beginPath(); ctx.arc(x, Y, rad, 0, 6.283); ctx.fill();
  }
  function blobFoot() {
    ctx.fillStyle = dk;
    ctx.beginPath(); ctx.ellipse(x, Y + R * .80, R * .86, R * .17, 0, 0, 6.283); ctx.fill();
  }
  if (glow) halo(R * 1.35, 'rgba(255,220,140,.20)');

  // ---------- 果凍（雪球、熔岩史萊姆）----------
  if (art === 'blob') {
    const sq = 1 + Math.sin(t * 6 + w) * .08;
    blobFoot();
    ctx.fillStyle = col;
    ctx.beginPath(); ctx.ellipse(x, Y + R * .18, R * .96 / sq, R * .84 * sq, 0, 0, 6.283); ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,.36)';
    ctx.beginPath(); ctx.ellipse(x - R * .30, Y - R * .18, R * .26, R * .16, -.5, 0, 6.283); ctx.fill();
    eyes(0, -R * .02, R * .12, R * .18);
    ctx.strokeStyle = '#141826'; ctx.lineWidth = Math.max(1, R * .09);
    ctx.beginPath(); ctx.arc(x, Y + R * .26, R * .17, .3, 2.84); ctx.stroke();
    ctx.lineWidth = 1;
    return;
  }

  // ---------- 蠕蟲（毛毛蟲、流沙蟲、熔岩蠕蟲）----------
  if (art === 'worm') {
    const n = sp.segs || 4;
    ctx.strokeStyle = dk; ctx.lineWidth = Math.max(1.2, R * .08); ctx.lineCap = 'round';
    for (let i = 0; i < n - 1; i++) {
      const lx = x - R * .55 + i * (R * 1.0 / (n - 1));
      const ly = Y + R * .44 + Math.sin(t * 5 + i) * R * .05;
      ctx.beginPath(); ctx.moveTo(lx, ly); ctx.lineTo(lx + step * 1.6, ly + R * .26); ctx.stroke();
    }
    ctx.lineWidth = 1;
    for (let i = n - 1; i >= 0; i--) {
      const sx = x + R * .58 - i * (R * 1.16 / (n - 1));
      const sy = Y + Math.sin(t * 5 + i * .9) * R * .10 + R * .12;
      const rr = R * (.42 - i * (.14 / n));
      ctx.fillStyle = (i % 2 === 0) ? col : dk;
      ctx.beginPath(); ctx.arc(sx, sy, rr, 0, 6.283); ctx.fill();
      if (i === 0) {
        ctx.fillStyle = 'rgba(255,255,255,.34)';
        ctx.beginPath(); ctx.arc(sx - rr * .3, sy - rr * .34, rr * .30, 0, 6.283); ctx.fill();
      }
    }
    eyes(R * .42, R * .04, R * .10, R * .14);
    return;
  }

  // ---------- 小動物（青蛙、兔、沙丘獸、海豹、燈籠魚）----------
  if (art === 'critter') {
    // 腳
    ctx.fillStyle = dk;
    [-1, 1].forEach(function (sd) {
      ctx.beginPath(); ctx.ellipse(x + sd * R * .40, Y + R * .56, R * .17, R * .11, 0, 0, 6.283); ctx.fill();
    });
    // 尾巴
    if (sp.ears === 'horn' || sp.tail) {
      ctx.strokeStyle = dk; ctx.lineWidth = Math.max(1.4, R * .10); ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(x - R * .62, Y + R * .18);
      ctx.quadraticCurveTo(x - R * 1.02, Y + R * .04, x - R * .96, Y - R * .26);
      ctx.stroke(); ctx.lineWidth = 1;
    }
    // 身體
    ctx.fillStyle = col;
    ctx.beginPath(); ctx.ellipse(x, Y + R * .20, R * .74, R * .62, 0, 0, 6.283); ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,.22)';
    ctx.beginPath(); ctx.ellipse(x - R * .18, Y - R * .02, R * .30, R * .18, -.4, 0, 6.283); ctx.fill();
    // 頭
    const hx = x + look * R * .24, hy = Y - R * .34;
    ctx.fillStyle = col;
    ctx.beginPath(); ctx.arc(hx, hy, R * .54, 0, 6.283); ctx.fill();
    // 耳朵／鰭
    if (sp.ears === 'long') {
      ctx.fillStyle = col;
      [-1, 1].forEach(function (sd) {
        ctx.beginPath();
        ctx.ellipse(hx + sd * R * .20, hy - R * .56, R * .12, R * .42, sd * .18, 0, 6.283);
        ctx.fill();
        ctx.fillStyle = 'rgba(255,150,180,.55)';
        ctx.beginPath();
        ctx.ellipse(hx + sd * R * .20, hy - R * .56, R * .06, R * .26, sd * .18, 0, 6.283);
        ctx.fill();
        ctx.fillStyle = col;
      });
    } else if (sp.ears === 'horn') {
      ctx.fillStyle = dk;
      [-1, 1].forEach(function (sd) {
        ctx.beginPath();
        ctx.moveTo(hx + sd * R * .30, hy - R * .34);
        ctx.lineTo(hx + sd * R * .46, hy - R * .86);
        ctx.lineTo(hx + sd * R * .10, hy - R * .44);
        ctx.closePath(); ctx.fill();
      });
    } else if (sp.ears === 'fin') {
      ctx.fillStyle = dk;
      [-1, 1].forEach(function (sd) {
        ctx.beginPath();
        ctx.moveTo(hx + sd * R * .42, hy - R * .10);
        ctx.lineTo(hx + sd * R * .74, hy - R * .34);
        ctx.lineTo(hx + sd * R * .44, hy + R * .16);
        ctx.closePath(); ctx.fill();
      });
    }
    // 眼睛（燈籠魚一大一小）
    eyes(look * R * .12, -R * .36, R * .12, R * .16);
    // 嘴
    ctx.fillStyle = dk;
    ctx.beginPath(); ctx.ellipse(hx, hy + R * .26, R * .16, R * .09, 0, 0, 6.283); ctx.fill();
    // 燈籠魚的提燈
    if (sp.lure) {
      ctx.strokeStyle = dk; ctx.lineWidth = Math.max(1.2, R * .07); ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(hx + look * R * .10, hy - R * .48);
      ctx.quadraticCurveTo(hx + look * R * .44, hy - R * 1.02, hx + look * R * .16, hy - R * 1.16);
      ctx.stroke(); ctx.lineWidth = 1;
      if (!flash) {
        ctx.fillStyle = '#fff6b0';
        ctx.beginPath(); ctx.arc(hx + look * R * .16, hy - R * 1.16, R * .14, 0, 6.283); ctx.fill();
        ctx.fillStyle = 'rgba(255,240,140,.28)';
        ctx.beginPath(); ctx.arc(hx + look * R * .16, hy - R * 1.16, R * .32, 0, 6.283); ctx.fill();
      }
    }
    return;
  }

  // ---------- 人形（木乃伊、小惡魔、近衛軍、死亡騎士）----------
  if (art === 'humanoid') {
    // 腿
    ctx.fillStyle = dk;
    [-1, 1].forEach(function (sd) {
      ctx.fillRect(x + sd * R * .30 - R * .12, Y + R * .40, R * .24, R * .42 + (sd > 0 ? step * .6 : -step * .6));
    });
    // 身體
    ctx.fillStyle = col;
    ctx.beginPath();
    ctx.moveTo(x - R * .46, Y + R * .44);
    ctx.lineTo(x - R * .34, Y - R * .30);
    ctx.lineTo(x + R * .34, Y - R * .30);
    ctx.lineTo(x + R * .46, Y + R * .44);
    ctx.closePath(); ctx.fill();
    // 手臂
    ctx.strokeStyle = col; ctx.lineWidth = Math.max(2, R * .18); ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(x - R * .40, Y - R * .16);
    ctx.lineTo(x - R * .72, Y + R * .20 + step);
    ctx.moveTo(x + R * .40, Y - R * .16);
    ctx.lineTo(x + R * .72, Y + R * .20 - step);
    ctx.stroke();
    ctx.lineWidth = 1;
    // 護甲
    if (sp.armor) {
      ctx.fillStyle = dk;
      ctx.beginPath();
      ctx.moveTo(x - R * .40, Y - R * .10);
      ctx.lineTo(x + R * .40, Y - R * .10);
      ctx.lineTo(x + R * .30, Y + R * .18);
      ctx.lineTo(x - R * .30, Y + R * .18);
      ctx.closePath(); ctx.fill();
      ctx.fillStyle = 'rgba(255,255,255,.18)';
      ctx.fillRect(x - R * .28, Y - R * .06, R * .56, R * .05);
    }
    // 繃帶
    if (sp.band) {
      ctx.strokeStyle = 'rgba(180,160,120,.85)'; ctx.lineWidth = Math.max(1, R * .06);
      for (let i = 0; i < 3; i++) {
        ctx.beginPath();
        ctx.moveTo(x - R * .36, Y - R * .18 + i * R * .18);
        ctx.lineTo(x + R * .36, Y - R * .14 + i * R * .18);
        ctx.stroke();
      }
      ctx.lineWidth = 1;
    }
    // 頭
    const hy = Y - R * .58;
    ctx.fillStyle = sp.band ? '#f7f2e4' : col;
    ctx.beginPath(); ctx.arc(x, hy, R * .44, 0, 6.283); ctx.fill();
    // 角
    if (sp.ears === 'horn') {
      ctx.fillStyle = dk;
      [-1, 1].forEach(function (sd) {
        ctx.beginPath();
        ctx.moveTo(x + sd * R * .26, hy - R * .28);
        ctx.quadraticCurveTo(x + sd * R * .60, hy - R * .62, x + sd * R * .30, hy - R * .80);
        ctx.quadraticCurveTo(x + sd * R * .40, hy - R * .52, x + sd * R * .10, hy - R * .30);
        ctx.closePath(); ctx.fill();
      });
    }
    eyes(0, -R * .60, R * .10, R * .14, sp.armor ? '#ff6a6a' : '#fff');
    return;
  }

  // ---------- 甲蟲／蠍子 ----------
  if (art === 'bug') {
    ctx.strokeStyle = dk; ctx.lineWidth = Math.max(1.6, R * .12); ctx.lineCap = 'round';
    for (let i = -1; i <= 1; i++) {
      const lx = x + i * R * .40;
      ctx.beginPath();
      ctx.moveTo(lx, Y + R * .40);
      ctx.quadraticCurveTo(lx + step * 1.4, Y + R * .74, lx + step * 2.4, Y + R * .92);
      ctx.stroke();
    }
    ctx.lineWidth = 1;
    // 尾巴（蠍子毒鉤）
    if (sp.tail) {
      ctx.strokeStyle = dk; ctx.lineWidth = Math.max(1.8, R * .14); ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(x - R * .70, Y + R * .16);
      ctx.quadraticCurveTo(x - R * 1.26, Y + R * .06, x - R * 1.06, Y - R * .52);
      ctx.stroke();
      ctx.lineWidth = 1;
      ctx.fillStyle = col;
      ctx.beginPath(); ctx.arc(x - R * 1.00, Y - R * .60, R * .16, 0, 6.283); ctx.fill();
    }
    ctx.fillStyle = dk;
    ctx.beginPath(); ctx.ellipse(x, Y + R * .14, R * 1.00, R * .88, 0, 0, 6.283); ctx.fill();
    ctx.fillStyle = col;
    ctx.beginPath(); ctx.ellipse(x, Y + R * .06, R * .90, R * .76, 0, 0, 6.283); ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,.30)'; ctx.lineWidth = Math.max(1, R * .09);
    ctx.beginPath(); ctx.moveTo(x, Y - R * .66); ctx.lineTo(x, Y + R * .76); ctx.stroke();
    ctx.lineWidth = 1;
    // 螯
    ctx.fillStyle = dk;
    [-1, 1].forEach(function (sd) {
      ctx.beginPath();
      ctx.moveTo(x + sd * R * .82, Y - R * .10);
      ctx.lineTo(x + sd * R * 1.24, Y - R * .30 - step);
      ctx.lineTo(x + sd * R * .86, Y + R * .10);
      ctx.closePath(); ctx.fill();
    });
    eyes(0, -R * .10, R * .11, R * .15);
    return;
  }

  // ---------- 冰晶 ----------
  if (art === 'crystal') {
    for (let i = 0; i < 3; i++) {
      const hh = R * (i === 1 ? 1.42 : .96);
      const ox = (i - 1) * R * .44;
      ctx.fillStyle = i === 1 ? col : dk;
      ctx.beginPath();
      ctx.moveTo(x + ox, Y - hh * .72);
      ctx.lineTo(x + ox + R * .26, Y - hh * .10);
      ctx.lineTo(x + ox, Y + hh * .56);
      ctx.lineTo(x + ox - R * .26, Y - hh * .10);
      ctx.closePath(); ctx.fill();
      ctx.fillStyle = 'rgba(255,255,255,.5)';
      ctx.beginPath();
      ctx.moveTo(x + ox, Y - hh * .70);
      ctx.lineTo(x + ox + R * .10, Y - hh * .12);
      ctx.lineTo(x + ox, Y + hh * .10);
      ctx.closePath(); ctx.fill();
    }
    eyes(0, -R * .06, R * .10, R * .13);
    return;
  }

  // ---------- 岩石怪 ----------
  if (art === 'golem') {
    ctx.fillStyle = dk;
    ctx.beginPath();
    ctx.moveTo(x - R * .84, Y + R * .58);
    ctx.lineTo(x - R * .70, Y - R * .34);
    ctx.lineTo(x - R * .16, Y - R * .82);
    ctx.lineTo(x + R * .60, Y - R * .52);
    ctx.lineTo(x + R * .84, Y + R * .28);
    ctx.lineTo(x + R * .30, Y + R * .68);
    ctx.closePath(); ctx.fill();
    ctx.fillStyle = col;
    ctx.beginPath();
    ctx.moveTo(x - R * .64, Y + R * .40);
    ctx.lineTo(x - R * .54, Y - R * .26);
    ctx.lineTo(x - R * .12, Y - R * .62);
    ctx.lineTo(x + R * .44, Y - R * .38);
    ctx.lineTo(x + R * .62, Y + R * .20);
    ctx.lineTo(x + R * .22, Y + R * .50);
    ctx.closePath(); ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,.35)'; ctx.lineWidth = Math.max(1, R * .07);
    ctx.beginPath();
    ctx.moveTo(x - R * .30, Y - R * .52); ctx.lineTo(x - R * .10, Y - R * .10);
    ctx.lineTo(x + R * .22, Y + R * .06);
    ctx.moveTo(x + R * .10, Y + R * .44); ctx.lineTo(x + R * .30, Y + R * .12);
    ctx.stroke();
    ctx.lineWidth = 1;
    eyes(0, -R * .10, R * .11, R * .14);
    return;
  }

  // ---------- 機械（霓虹機器人）----------
  if (art === 'machine') {
    ctx.fillStyle = dk;
    ctx.fillRect(x - R * .56, Y + R * .46, R * 1.12, R * .30);
    ctx.fillStyle = 'rgba(255,255,255,.20)';
    ctx.fillRect(x - R * .50, Y + R * .52, R * 1.00, R * .06);
    ctx.fillStyle = col;
    ctx.beginPath();
    ctx.moveTo(x - R * .62, Y + R * .46);
    ctx.lineTo(x - R * .54, Y - R * .42);
    ctx.lineTo(x + R * .54, Y - R * .42);
    ctx.lineTo(x + R * .62, Y + R * .46);
    ctx.closePath(); ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,.22)';
    ctx.fillRect(x - R * .42, Y - R * .34, R * .34, R * .70);
    // 面罩
    ctx.fillStyle = '#101a28';
    ctx.fillRect(x - R * .34, Y - R * .22, R * .68, R * .30);
    if (!flash) {
      ctx.fillStyle = '#8ffff0';
      ctx.fillRect(x - R * .26, Y - R * .16, R * .18, R * .10);
      ctx.fillRect(x + R * .08, Y - R * .16, R * .18, R * .10);
    }
    // 天線
    ctx.strokeStyle = dk; ctx.lineWidth = Math.max(1.2, R * .08);
    ctx.beginPath(); ctx.moveTo(x, Y - R * .42); ctx.lineTo(x, Y - R * .78); ctx.stroke();
    ctx.lineWidth = 1;
    if (!flash) {
      ctx.fillStyle = '#ff6a9a';
      ctx.beginPath(); ctx.arc(x, Y - R * .82, R * .10, 0, 6.283); ctx.fill();
    }
    return;
  }

  // ---------- 電音精靈 ----------
  if (art === 'sprite') {
    const pulse = .5 + Math.abs(Math.sin(t * 5)) * .5;
    if (!flash) {
      ctx.strokeStyle = 'rgba(255,120,230,' + (.30 + pulse * .40).toFixed(2) + ')';
      ctx.lineWidth = Math.max(1.4, R * .09);
      ctx.beginPath(); ctx.ellipse(x, Y + R * .06, R * (.86 + pulse * .12), R * .30, .5, 0, 6.283); ctx.stroke();
      ctx.lineWidth = 1;
    }
    ctx.fillStyle = col;
    ctx.beginPath(); ctx.arc(x, Y, R * .56, 0, 6.283); ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,.44)';
    ctx.beginPath(); ctx.arc(x - R * .16, Y - R * .18, R * .20, 0, 6.283); ctx.fill();
    eyes(0, -R * .04, R * .10, R * .14);
    // 音符火花
    if (!flash) {
      ctx.fillStyle = 'rgba(255,220,255,.85)';
      for (let i = 0; i < 3; i++) {
        const a = t * 2.4 + i * 2.1;
        ctx.beginPath();
        ctx.arc(x + Math.cos(a) * R * .86, Y + Math.sin(a) * R * .56, R * .09, 0, 6.283);
        ctx.fill();
      }
    }
    return;
  }

  // ---------- 鳥／蝙蝠／蜂 ----------
  if (art === 'bird') {
    const flap = Math.sin(t * 14 + (sp.spd || 40)) ;
    ctx.fillStyle = flash ? '#fff' : 'rgba(255,255,255,.55)';
    [-1, 1].forEach(function (sd) {
      ctx.beginPath();
      ctx.moveTo(x + sd * R * .24, Y - R * .04);
      ctx.quadraticCurveTo(x + sd * R * .96, Y - R * (.34 + flap * .26), x + sd * R * 1.10, Y + R * .16);
      ctx.quadraticCurveTo(x + sd * R * .70, Y + R * .16, x + sd * R * .26, Y + R * .20);
      ctx.closePath(); ctx.fill();
    });
    ctx.fillStyle = col;
    ctx.beginPath(); ctx.ellipse(x, Y + R * .06, R * .60, R * .54, 0, 0, 6.283); ctx.fill();
    ctx.fillStyle = dk;
    ctx.beginPath();
    ctx.moveTo(x - R * .50, Y + R * .12);
    ctx.lineTo(x - R * .96, Y - R * .10);
    ctx.lineTo(x - R * .92, Y + R * .34);
    ctx.closePath(); ctx.fill();
    ctx.fillStyle = '#f2b23c';
    ctx.beginPath();
    ctx.moveTo(x + look * R * .52, Y + R * .02);
    ctx.lineTo(x + look * R * .92, Y + R * .14);
    ctx.lineTo(x + look * R * .52, Y + R * .24);
    ctx.closePath(); ctx.fill();
    eyes(0, -R * .10, R * .10, R * .13);
    return;
  }

  // ---------- 寄居蟹（殼）----------
  if (art === 'shell') {
    ctx.strokeStyle = dk; ctx.lineWidth = Math.max(1.4, R * .10); ctx.lineCap = 'round';
    [-1, 1].forEach(function (sd) {
      for (let i = 0; i < 2; i++) {
        ctx.beginPath();
        ctx.moveTo(x + sd * R * .30, Y + R * .30 + i * R * .14);
        ctx.lineTo(x + sd * R * .74, Y + R * .52 + i * R * .16 + step);
        ctx.stroke();
      }
    });
    ctx.lineWidth = 1;
    // 殼（螺旋）
    ctx.fillStyle = dk;
    ctx.beginPath(); ctx.arc(x - R * .16, Y - R * .10, R * .76, 0, 6.283); ctx.fill();
    ctx.fillStyle = col;
    ctx.beginPath(); ctx.arc(x - R * .16, Y - R * .10, R * .64, 0, 6.283); ctx.fill();
    ctx.strokeStyle = 'rgba(255,255,255,.55)'; ctx.lineWidth = Math.max(1.2, R * .08);
    for (let i = 0; i < 2; i++) {
      ctx.beginPath();
      ctx.arc(x - R * .16, Y - R * .10, R * (.30 + i * .22), i * 1.2, i * 1.2 + 3.6);
      ctx.stroke();
    }
    ctx.lineWidth = 1;
    // 眼柄
    [-1, 1].forEach(function (sd) {
      ctx.strokeStyle = dk; ctx.lineWidth = Math.max(1.2, R * .08);
      ctx.beginPath();
      ctx.moveTo(x + R * .34, Y + R * .06);
      ctx.lineTo(x + sd * R * .34 + R * .10, Y - R * .46);
      ctx.stroke();
      ctx.lineWidth = 1;
      ctx.fillStyle = '#fff';
      ctx.beginPath(); ctx.arc(x + sd * R * .34 + R * .10, Y - R * .50, R * .12, 0, 6.283); ctx.fill();
      ctx.fillStyle = '#141826';
      ctx.beginPath(); ctx.arc(x + sd * R * .34 + R * .10, Y - R * .50, R * .06, 0, 6.283); ctx.fill();
    });
    return;
  }

  // ---------- 水母 ----------
  if (art === 'jelly') {
    const pulse = .5 + Math.abs(Math.sin(t * 2.6)) * .5;
    ctx.strokeStyle = dk; ctx.lineWidth = Math.max(1.2, R * .07); ctx.lineCap = 'round';
    for (let i = -2; i <= 2; i++) {
      const bx = x + i * R * .26;
      ctx.beginPath();
      ctx.moveTo(bx, Y + R * .30);
      ctx.quadraticCurveTo(bx + Math.sin(t * 3 + i) * R * .16, Y + R * .70, bx + Math.sin(t * 3 + i) * R * .22, Y + R * .96);
      ctx.stroke();
    }
    ctx.lineWidth = 1;
    ctx.fillStyle = col;
    ctx.beginPath();
    ctx.moveTo(x - R * (.62 + pulse * .06), Y + R * .30);
    ctx.quadraticCurveTo(x - R * .70, Y - R * .62, x, Y - R * .66);
    ctx.quadraticCurveTo(x + R * .70, Y - R * .62, x + R * (.62 + pulse * .06), Y + R * .30);
    ctx.quadraticCurveTo(x, Y + R * .46, x - R * (.62 + pulse * .06), Y + R * .30);
    ctx.closePath(); ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,.42)';
    ctx.beginPath(); ctx.ellipse(x - R * .22, Y - R * .34, R * .20, R * .12, -.3, 0, 6.283); ctx.fill();
    eyes(0, -R * .12, R * .10, R * .13);
    return;
  }

  // ---------- 尖刺球（海膽、雷電球）----------
  if (art === 'spike') {
    const sp2 = 8;
    ctx.strokeStyle = dk; ctx.lineWidth = Math.max(1.4, R * .10); ctx.lineCap = 'round';
    for (let i = 0; i < sp2; i++) {
      const a = i * (6.283 / sp2) + t * .8;
      ctx.beginPath();
      ctx.moveTo(x + Math.cos(a) * R * .52, Y + Math.sin(a) * R * .52);
      ctx.lineTo(x + Math.cos(a) * R * 1.02, Y + Math.sin(a) * R * 1.02);
      ctx.stroke();
    }
    ctx.lineWidth = 1;
    ctx.fillStyle = col;
    ctx.beginPath(); ctx.arc(x, Y, R * .60, 0, 6.283); ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,.34)';
    ctx.beginPath(); ctx.arc(x - R * .16, Y - R * .18, R * .18, 0, 6.283); ctx.fill();
    eyes(0, 0, R * .10, R * .13);
    return;
  }

  // ---------- 幽靈／風精靈 ----------
  if (art === 'ghost') {
    ctx.fillStyle = col;
    ctx.beginPath();
    ctx.arc(x, Y - R * .12, R * .62, 3.1416, 0);
    ctx.lineTo(x + R * .62, Y + R * .44);
    for (let i = 2; i >= -2; i--) {
      const wx = x + i * R * .248;
      const wy = Y + R * .44 + ((i % 2 === 0) ? R * .16 : -R * .06) + Math.sin(t * 6 + i) * R * .06;
      ctx.lineTo(wx, wy);
    }
    ctx.closePath(); ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,.30)';
    ctx.beginPath(); ctx.ellipse(x - R * .20, Y - R * .34, R * .18, R * .12, -.4, 0, 6.283); ctx.fill();
    eyes(0, -R * .16, R * .10, R * .13);
    return;
  }

  // ---------- 飛艇 ----------
  if (art === 'ship') {
    ctx.fillStyle = 'rgba(255,255,255,.30)';
    ctx.beginPath(); ctx.ellipse(x, Y - R * .30, R * .88, R * .56, 0, 0, 6.283); ctx.fill();
    ctx.fillStyle = col;
    ctx.beginPath(); ctx.ellipse(x, Y - R * .32, R * .72, R * .48, 0, 0, 6.283); ctx.fill();
    ctx.strokeStyle = dk; ctx.lineWidth = Math.max(1.2, R * .07);
    ctx.beginPath(); ctx.moveTo(x - R * .72, Y - R * .32); ctx.lineTo(x + R * .72, Y - R * .32); ctx.stroke();
    ctx.lineWidth = 1;
    // 吊籃
    ctx.fillStyle = dk;
    ctx.beginPath();
    ctx.moveTo(x - R * .36, Y + R * .06);
    ctx.lineTo(x + R * .36, Y + R * .06);
    ctx.lineTo(x + R * .26, Y + R * .46);
    ctx.lineTo(x - R * .26, Y + R * .46);
    ctx.closePath(); ctx.fill();
    // 螺旋槳
    const p2 = Math.sin(t * 18) * R * .16;
    ctx.strokeStyle = 'rgba(230,240,255,.9)'; ctx.lineWidth = Math.max(1.2, R * .07);
    ctx.beginPath();
    ctx.moveTo(x + R * .36, Y + R * .26); ctx.lineTo(x + R * .36, Y + R * .26 + p2);
    ctx.stroke(); ctx.lineWidth = 1;
    // 窗
    ctx.fillStyle = '#8ffff0';
    ctx.beginPath(); ctx.arc(x, Y + R * .24, R * .12, 0, 6.283); ctx.fill();
    return;
  }

  // 保險：未知的 art → 畫成最基本的小果凍
  ctx.fillStyle = col;
  ctx.beginPath(); ctx.ellipse(x, Y, R * .86, R * .78, 0, 0, 6.283); ctx.fill();
  eyes(0, 0, R * .12, R * .16);
}

