    ctx.beginPath(); ctx.moveTo(x + R * .04, yb - R * .3); ctx.lineTo(x + R * .14, yb - R * .12); ctx.lineTo(x + R * .22, yb - R * .3); ctx.closePath(); ctx.fill();
    return;
