function drawRigChar(g, key, x, footY, H, a) {
  if (!g || !g.drawImage || typeof IMG_PARTS === 'undefined') return null;
  /* v5.73：統一落地投影 —— 光源固定在左上，影子一律落在腳下偏右。
     以前每個分件自己帶陰影，方向不一致；現在底下一律墊一顆橢圓，角色才「站在地上」。 */
  try {
    if (g.ellipse) {
      g.save();
      g.globalAlpha = .22;
      g.fillStyle = '#0a0416';
      g.beginPath();
      g.ellipse(x + H * .05, footY - H * .02, H * .27, H * .085, 0, 0, 6.2832);
      g.fill();
      g.restore();
    }
  } catch (e) {}
  // v5.90：有影片精靈動畫的角色（目前只有 rabbit）優先走精靈，零件版留著當後備。
  if (typeof HeroAnim !== 'undefined' && HeroAnim && typeof HeroAnim.draw === 'function' &&
      typeof HeroAnim.has === 'function' && HeroAnim.has(key)) {
    const r = HeroAnim.draw(g, key, x, footY, H, a || {});
    if (r) return r;
  }
  const M = IMG_PARTS[key];
  if (!M || !Parts.has(key)) return null;
  a = a || {};
  const W = H * M.asp;
  const ox = x - W / 2, oy = footY - H;
  const moving = !!a.moving;
  const w = a.walk || 0;
  const amp = a.amp == null ? 1 : a.amp;
  const fx = DIRS[a.facing] || DIRS.down;
  // v4.29：M.dir = 原圖的預設朝向；side 是「相對原圖」要翻的方向
  const side = (fx.x < 0 ? -1 : 1) * (M.dir || 1);
  const step = moving ? Math.sin(w) : 0;
  const sq = moving ? Math.sin(w * 2) * .05 * amp : Math.sin((a.idle || 0) * 2.1) * .012;
  const jump = a.jump || 0;

  g.save();
  g.translate(x, footY - jump);
  g.scale(side * (1 + sq * .30), 1 - sq);
  g.translate(-x, -footY);
  if (a.expr === 'hurt') { try { g.filter = 'brightness(1.25) saturate(2.2) hue-rotate(-14deg)'; } catch (e) {} }
  if (a.alpha != null) { try { g.globalAlpha = a.alpha; } catch (e) {} }

  function put(pn, ang, dx, dy, sx, sy) {
    const d = M.p[pn];
    const im = Parts.get(key, pn);
    if (!d || !im) return;
    const px = ox + d.x * W, py = oy + d.y * H;
    const pw = d.w * W, ph = d.h * H;
    const ux = ox + d.px * W, uy = oy + d.py * H;
    g.save();
    g.translate(ux + (dx || 0), uy + (dy || 0));
    if (ang) g.rotate(ang);
    if ((sx && sx !== 1) || (sy && sy !== 1)) g.scale(sx || 1, sy || 1);
    g.translate(-ux, -uy);
    g.drawImage(im, px, py, pw, ph);
    g.restore();
  }

  // 尾巴（狗／貓）：隨身體慢擺
  if (M.p.tail) put('tail', Math.sin((a.idle || 0) * 1.6) * .20 * amp + step * .12 * amp, 0, 0);
  // 腿：左右交替抬腳（step > 0 抬左腿）
  put('legL', -step * .10 * amp, 0, -Math.max(0, step) * H * .05 * amp);
  put('legR', step * .10 * amp, 0, -Math.max(0, -step) * H * .05 * amp);
  // 身體：擠壓 + 微傾
  put('torso', step * .022 * amp, step * W * .012 * amp, 0, 1, 1 - sq * .45);
  // 手臂：前後擺（跟腿相反）
  const armSw = (a.armSwing == null ? .22 : a.armSwing) * amp;
  put('armL', -step * armSw, 0, -step * H * .012 * amp);
  put('armR', step * armSw, 0, step * H * .012 * amp);
  // 頭：點一下 + 微微左右擺（最後畫，順便蓋住脖子接縫）
  const headBob = moving ? Math.abs(Math.sin(w)) * H * .014 * amp : Math.sin((a.idle || 0) * 1.7) * H * .008;
  put('head', step * .05 * amp + (a.headTilt || 0), 0, -headBob);
  try { g.filter = 'none'; } catch (e) {}
  g.restore();

  // v4.29：表情＝頭頂情緒圖示 ＋ 身體周圍特效（不覆蓋原臉）。
  // 自然狀態（a.expr 為空）完全不畫 → 角色保持原圖的乾淨笑臉。
  // 注意：一定要畫在 g.restore() 之後，否則會被「鏡像 + 擠壓」的變換帶歪。
  const mood = heroMood(a);
  if (mood) {
    const hd = M.p.head;
    const hbx = hd ? ox + hd.x * W : x - W * .3;
    const hby = hd ? oy + hd.y * H : oy;
    const hbw = hd ? hd.w * W : W * .6;
    const hbh = hd ? hd.h * H : H * .3;
    heroMoodVfx(g, mood, x, footY - jump, H, a.idle || 0,
                { x: hbx, y: hby, w: hbw, h: hbh });
    // v5.31：情緒頭像放大 34%（H*.16 → H*.215）
    // v5.32：放大後圓框會整個蓋住臉（直徑 ≈ 半個角色高）→ 改成浮在頭頂上方的對話泡泡，尾巴尖端指著頭
    heroEmoteIcon(g, mood, hbx + hbw * .5, hby - H * .275, H * .215, a.idle || 0, 1);
  }
  return { topY: oy + H * .08, ex: fx.x * W * .06, ey: 0, H: H, W: W };
}

// ---------- 精靈圖：使用者提供的原圖（已摳成透明背景） ----------
