refreshers.push(segWire('segTpadSide', function () { return settings.tpad.side; }, function (v) { settings.tpad.side = v; applyTouchLayout(); }));
refreshers.push(segWire('segTactSide', function () { return settings.tpad.act; }, function (v) { settings.tpad.act = v; applyTouchLayout(); }));
refreshers.push(segWire('segTsize', function () { return settings.tpad.size; }, function (v) { settings.tpad.size = parseFloat(v) || 1; applyTouchLayout(); }));

// ---------- 鍵盤改鍵 ----------
const KEY_ORDER = ['up', 'down', 'left', 'right', 'act', 'det', 'fire'];
const KEY_LABELS = { up: 'key.up', down: 'key.down', left: 'key.left', right: 'key.right', act: 'key.act', det: 'key.det', fire: 'key.fire' };
let keyPlayer = 1;
let capturing = null;
function keyName(code) {
  if (!code) return '未設定';
  // v5.11：滑鼠鍵（'Mouse0' 左／'Mouse1' 中／'Mouse2' 右）
  if (/^Mouse[0-9]$/.test(code)) {
    const mb = { Mouse0: '滑鼠左鍵', Mouse1: '滑鼠中鍵', Mouse2: '滑鼠右鍵' };
    return mb[code] || '滑鼠';
  }
  const named = {
    Space: '空白鍵', Enter: 'Enter', Escape: 'ESC', Tab: 'Tab', Backspace: 'Backspace',
    ShiftLeft: 'Shift(左)', ShiftRight: 'Shift(右)', ControlLeft: 'Ctrl(左)', ControlRight: 'Ctrl(右)',
    AltLeft: 'Alt(左)', AltRight: 'Alt(右)', CapsLock: 'CapsLock',
    ArrowUp: '↑', ArrowDown: '↓', ArrowLeft: '←', ArrowRight: '→',
    Comma: ',', Period: '.', Semicolon: ';', Slash: '/', Quote: "'", BracketLeft: '[',
    BracketRight: ']', Backquote: '`', Minus: '-', Equal: '=', Backslash: '\\'
  };
  if (named[code]) return named[code];
  if (/^Key[A-Z]$/.test(code)) return code.slice(3);
  if (/^Digit[0-9]$/.test(code)) return code.slice(5);
  if (/^Numpad/.test(code)) return 'Num' + code.slice(6);
  return code;
}
function curKeys() { return keyPlayer === 1 ? settings.keys1 : settings.keys2; }
// v5.11：操作設定底部的現況摘要（改鍵或改滑鼠鍵都會跟著更新）
function refreshCmdHint() {
  const el = $id('setCmdHint');
  if (!el) return;
  const k = (keyPlayer === 1 ? settings.keys1 : settings.keys2) || {};
  const esc = (typeof hesc === 'function') ? hesc : function (s) { return s; };
  /* v5.54：整句改成單一模板 key —— 原本是「中文碎片 + <b>鍵名</b>」串起來的，
     逐節點翻不動、拼起來的語序也沒辦法翻。 */
  el.innerHTML = t('cmd.hint', {
    n: keyPlayer,
    u: esc(tr(keyName(k.up))), l: esc(tr(keyName(k.left))),
    d: esc(tr(keyName(k.down))), r: esc(tr(keyName(k.right))),
    act: esc(tr(keyName(k.act))), det: esc(tr(keyName(k.det))),
    fire: esc(tr(keyName(k.fire)))
  });
}
function renderKeyRow() {
  const row = $id('keyRow');
  if (!row) return;
  const map = curKeys();
  row.innerHTML = KEY_ORDER.map(function (k) {
    return '<button class="keybtn" data-k="' + k + '"><small>' + t(KEY_LABELS[k]) + '</small><b>' +
      tr(keyName(map[k])) + '</b></button>';
  }).join('');
  Array.prototype.forEach.call(row.querySelectorAll('.keybtn'), function (btn) {
    btn.addEventListener('click', function () { startCapture(btn.getAttribute('data-k'), btn); });
  });
  try { refreshCmdHint(); } catch (e) {}
}
function startCapture(k, btn) {
  if (capturing && capturing.el) {
    capturing.el.classList.remove('listening');
    renderKeyRow();
    capturing = null;
    return;
  }
  capturing = { k: k, el: btn };
  btn.classList.add('listening');
  btn.innerHTML = '<small>' + t(KEY_LABELS[k]) + '</small><b>' + t('key.press') + '</b>';
  AudioSys.sfx('click');
}
function cancelCapture() {
  if (!capturing) return;
  if (capturing.el) capturing.el.classList.remove('listening');
  capturing = null;
  renderKeyRow();
}
function applyCapture(code) {
  if (!capturing) return;
  const map = curKeys();
  const other = KEY_ORDER.filter(function (x) { return x !== capturing.k && map[x] === code; })[0];
  if (other) map[other] = null;   // 同鍵衝突 → 舊的先清掉
  map[capturing.k] = code;
  saveSettings();
  AudioSys.sfx('item');
  capturing = null;
  renderKeyRow();
}
window.addEventListener('keydown', function (e) {
  if (!capturing) return;
  if (e.preventDefault) e.preventDefault();
  if (e.stopPropagation) e.stopPropagation();
  if (e.code === 'Escape') { cancelCapture(); return; }
  applyCapture(e.code);
}, true);
// v5.11：改鍵也能直接「按一下滑鼠鍵」（放炸彈＝左鍵、引爆＝右鍵、衝刺＝中鍵）
window.addEventListener('mousedown', function (e) {
  if (!capturing) return;
  if (e.preventDefault) e.preventDefault();
  if (e.stopPropagation) e.stopPropagation();
  const b = e.button | 0;
  if (b > 2) return;
  applyCapture('Mouse' + b);
}, true);
  try {
(function wireKeyUI() {
  const seg = $id('segKeyP');
  function refreshP() {
    if (!seg || !seg.querySelectorAll) return;
    Array.prototype.forEach.call(seg.querySelectorAll('button'), function (b) {
      b.classList.toggle('sel', b.getAttribute('data-v') === String(keyPlayer));
    });
  }
  if (seg && seg.querySelectorAll) {
    Array.prototype.forEach.call(seg.querySelectorAll('button'), function (b) {
      b.addEventListener('click', function () {
        AudioSys.sfx('click');
        keyPlayer = parseInt(b.getAttribute('data-v'), 10) === 2 ? 2 : 1;
        cancelCapture();
        refreshP();
        renderKeyRow();
      });
    });
  }
  refreshP();
  renderKeyRow();
  const reset = $id('btnKeyReset');
  if (reset) reset.addEventListener('click', function () {
    AudioSys.sfx('click');
    const def = keyPlayer === 1 ? DEF_KEYS1 : DEF_KEYS2;
    const map = curKeys();
    KEY_ORDER.forEach(function (k) { map[k] = def[k]; });
    saveSettings();
    cancelCapture();
    renderKeyRow();
  });
  const cancel = $id('btnKeyCancel');
  if (cancel) cancel.addEventListener('click', function () { AudioSys.sfx('click'); cancelCapture(); });
})();
  } catch (__e) { __bootFail('wire', __e); }

