/* v5.0：冒險入口 —— 單人闖關與 RPG 收進同一個彈窗，首頁少一顆按鈕 */
function showAdvPick(on) {
  const m = $id('bhPick');
  if (!m) return;
  m.classList.toggle('on', !!on);
  if (!on) return;
  const a = $id('bhPickTitle'), b = $id('bhPickDesc'), c = $id('bhPickTip'), d = $id('bhPickBack');
  if (a) a.textContent = t('adv.title');
  if (b) b.textContent = t('adv.desc');
  if (c) c.textContent = t('adv.tip');
  if (d) d.textContent = t('adv.back');
  const s1 = $id('btnSolo'), s2 = $id('btnRpg');
  if (s1) s1.textContent = t('adv.solo');
  if (s2) s2.textContent = t('adv.rpg');
  /* v5.73：深淵按鈕 —— 鎖住時直接寫「還差幾關」 */
  const ab = $id('btnAbyss'), at = $id('abyssTip');
  if (ab) {
    const ok = Abyss.unlocked();
    ab.classList.toggle('locked', !ok);
    const lv = ab.querySelector('b');
    if (at) {
      at.textContent = ok
        ? t('abyss.bestShort', { n: Abyss.bestOf() })
        : t('abyss.needMore', { n: Math.max(0, SOLO_STAGES - (Solo.unlocked | 0)) });
    }
  }
}
/* v5.73：深淵入口。40 關全破才開 —— 沒破關的人點下去要知道「還差什麼」，
   不是按了沒反應。 */
(function () {
  const b = $id('btnAbyss');
  if (b && b.addEventListener) b.addEventListener('click', function () {
    AudioSys.ensure(); AudioSys.sfx('click');
    if (!ensureNickname()) return;
    if (!Abyss.unlocked()) { AudioSys.sfx('hurt'); toast(t('abyss.locked'), 3); return; }
    /* v5.87：入場費在這裡收 —— 在 showAdvPick(false) 之前，
       付不起就留在原地，不會出現「選單關了、遊戲沒開」的懸空狀態。 */
    const fee = Abyss.entryFee ? Abyss.entryFee() : 0;
    if (fee > 0) {
      const r = Shop.spend(fee);
      if (!r || !r.ok) {
        AudioSys.sfx('nope');
        const need = Math.max(0, fee - (Shop.gold ? Shop.gold() : 0));
        toast(t('abyss.needGold', { n: need }), 3);
        return;
      }
    }
    showAdvPick(false);
    try { Abyss.start(1); } catch (e) { try { toast('深淵載入失敗，請重新整理', 2.6); } catch (e2) {} }
  });
})();
(function () {
  const adv = $id('btnAdventure');
  if (adv && adv.addEventListener) adv.addEventListener('click', function () {
    AudioSys.ensure(); AudioSys.sfx('click');
    setDrawer(false);
    showAdvPick(true);
  });
  const bk = $id('bhPickBack');
  if (bk && bk.addEventListener) bk.addEventListener('click', function () { AudioSys.sfx('click'); showAdvPick(false); });
  const mp = $id('bhPick');
  if (mp && mp.addEventListener) mp.addEventListener('click', function (e) { if (e.target === this) showAdvPick(false); });
  ['btnSolo', 'btnRpg'].forEach(function (k) {
    const b = $id(k);
    if (b && b.addEventListener) b.addEventListener('click', function () { showAdvPick(false); });
  });
})();
// v4.8：固定暱稱（首次玩必須先命名，之後都用這個）
  try {
(function () {
  const el = $id('playerName');
  if (el) {
    el.value = settings.playerName || '';
    el.addEventListener('input', function () {
      settings.playerName = String(el.value || '').trim().slice(0, 8);
      settings.nameAuto = 0;        // v5.71：玩家自己打的字 → 不再是「系統自動取名」
      saveSettings();
      const nm = $id('netName');
      if (nm && !nm.value) nm.value = settings.playerName;
    });
  }
})();
    /* v5.71：招呼語。migrate() 把「已經有名字的老玩家」標成定案，
       然後畫出招呼語（有定案才畫，沒定案時首頁仍然是原本的輸入框）。 */
    try { Nick.migrate(); Nick.wire(); Nick.greet(); } catch (__n) {}
  } catch (__e) { __bootFail('wire', __e); }
// v4.18：暱稱可以留空 —— 沒填就自動取一個「玩家xxx」，之後仍可在首頁改
function autoNickname() {
  const n = '玩家' + (100 + Math.floor(Math.random() * 900));
  settings.playerName = n;
  settings.nameAuto = 1;          // v5.71：系統取的名字不算定案 → 玩家不改也不用付錢
  settings.nameLock = 0;
  saveSettings();
  const el = $id('playerName');
  if (el) el.value = n;
  const nm = $id('netName');
  if (nm && !nm.value) nm.value = n;
  return n;
}
function ensureNickname() {
  if (settings.playerName) return true;
  const n = autoNickname();
  toast(t('nick.auto', { n: n }), 3, 'gear');
  return true;
}
// v1.9：明顯的「開始遊戲」大按鈕
$id('btnSoloGo').addEventListener('click', function () { AudioSys.ensure(); AudioSys.sfx('click'); Solo.go(); });
/* v5.66：移除「跳過關卡，直接單挑最終魔王」（v4.81 從首頁搬進來的那顆）。
   40 關制下每 5 關就有一場王的決戰場、第 40 關就是最終魔王，
   一鍵跳到最後等於把整條進度線作廢，所以連同 goBoss() 與 ?boss=1 一起拿掉。 */
// 單人難易度 / 關卡時間
function updateSoloHints() {
  const dh = $id('soloDiffHint'), th = $id('soloTimeHint');
  if (dh) dh.innerHTML = t('hint.diff.' + settings.soloDiff) || '';
  if (th) th.innerHTML = soloTimeVal() ? t('hint.time.on') : t('hint.time.off');
}
// v4.69：地圖模式（單人／RPG 共用同一個設定）
function mapModeHintTxt() {
  return t(mapModeRandom() ? 'mapmode.hint.random' : 'mapmode.hint.classic');
}
function paintMapModeUI() {
  const lbl = $id('soloMapLbl'); if (lbl) lbl.textContent = t('mapmode.title');
  [['segSoloMap', 'soloMapHint'], ['segRpgMode', 'rpgMapHint']].forEach(function (pair) {
    const seg = $id(pair[0]);
    if (seg) {
      seg.querySelectorAll('button').forEach(function (b) {
        b.textContent = b.getAttribute('data-v') === 'random' ? t('mapmode.random') : t('mapmode.classic');
      });
    }
    const h = $id(pair[1]); if (h) h.textContent = mapModeHintTxt();
  });
}
function mapModeChanged() {
  paintMapModeUI();
  try { Solo.renderGo(); } catch (e) {}
}
refreshers.push(paintMapModeUI);
refreshers.push(segWire('segSoloMap', function () { return settings.mapMode; }, function (v) {
  settings.mapMode = v; mapModeChanged();
}));
refreshers.push(segWire('segRpgMode', function () { return settings.mapMode; }, function (v) {
  settings.mapMode = v; mapModeChanged();
}));
paintMapModeUI();
refreshers.push(segWire('segSoloDiff', function () { return settings.soloDiff; }, function (v) {
  settings.soloDiff = v; updateSoloHints();
}));
refreshers.push(segWire('segSoloTime', function () { return settings.soloTime; }, function (v) {
  settings.soloTime = parseInt(v, 10) || 0; updateSoloHints();
}));
updateSoloHints();

