function brCardHTML() {
  const o = BR.opt;
  // v5.11：自己的角色索引（超出範圍或負數都收回 0~n-1）
  function brIdx() {
    const n = CHARACTERS.length;
    return (((settings.brChar | 0) % n) + n) % n;
  }
  function seg(k, arr) {
    return '<div class="brseg" data-k="' + k + '">' + arr.map(function (v) {
      return '<b data-v="' + v[0] + '"' + ((o[k] | 0) === (v[0] | 0) ? ' class="on"' : '') + '>' + v[1] + '</b>';
    }).join('') + '</div>';
  }
  let tkN = 0;
  try { tkN = Shop.tickets ? Shop.tickets() : 0; } catch (e) {}
  // v5.37：地圖尺寸先選 —— 大圖最多 100 人、原圖最多 50 人（人數選項跟著換）
  const bigSel = (o.map | 0) !== 0;
  const mw = bigSel ? 79 : 56, mh = bigSel ? 62 : 44;
  const ppl = bigSel
    ? [[30, t('br.p30')], [50, t('br.p50')], [100, t('br.p100')]]
    : [[20, t('br.p20')], [30, t('br.p30')], [50, t('br.p50')]];
  if (bigSel ? ((o.n | 0) > 100) : ((o.n | 0) > 50)) o.n = bigSel ? 100 : 50;
  const n = o.n | 0, tm = o.team | 0, du = o.dur | 0;
  return '<div class="brc">' +
    '<div class="brc-h"><b>🏝️ ' + t('br.title') + '</b><span>' + t('br.sub', { w: mw, h: mh }) + '</span>' +
    '<button class="brc-x" id="brOk" type="button">✕</button></div>' +
    '<div class="brrow"><label class="brlab">' + t('br.map') + '</label>' + seg('map', [[0, t('br.mapS')], [1, t('br.mapL')]]) + '</div>' +
    '<div class="brrow"><label class="brlab">' + t('br.people') + '</label>' + seg('n', ppl) + '</div>' +
    '<div class="brrow"><label class="brlab">' + t('br.team') + '</label>' +
      seg('team', [[1, t('br.solo')], [2, t('br.teamN', { n: 2 })], [3, t('br.teamN', { n: 3 })], [4, t('br.teamN', { n: 4 })]]) + '</div>' +
    '<div class="brrow"><label class="brlab">' + t('br.time') + '</label>' +
      seg('dur', [[5, t('br.d5')], [10, t('br.d10')]]) + '</div>' +
    /* v5.11：比照對戰的選角 —— 頭像左右切換 ＋ 可以自己命名（只影響顯示名字，不改帳號暱稱） */
    '<div class="brrow brwho"><label class="brlab">' + t('br.myChar') + '</label>' +
      '<div class="brchar">' +
        '<button class="brarr" type="button" data-chd="-1" title="' + t('br.chPrev') + '">◀</button>' +
        '<canvas class="chpv brchpv" width="220" height="200" data-ch="' + brIdx() + '"></canvas>' +
        '<button class="brarr" type="button" data-chd="1" title="' + t('br.chNext') + '">▶</button>' +
        '<input class="brname" id="brName" type="text" maxlength="8" autocomplete="off" ' +
          'placeholder="' + hesc(charName(CHARACTERS[brIdx()])) + '" value="' + hesc(settings.brName || '') + '">' +
      '</div></div>' +
    '<div class="brrow"><label class="brlab">' + t('br.bet') + '</label>' +
      seg('bet', [[0, t('br.betOff')], [500, '500'], [2000, '2000'], [5000, '5000']]) + '</div>' +
    '<div class="brrow brtiprow"><span class="brbettip">' + t('br.betTip') + '</span></div>' +
    '<div class="brsum" id="brSum">' + brSumText() + '</div>' +
    '<div class="brgo-box"><button class="mbtn warm" id="brGo" type="button">' +
      (tm >= 2 ? t('br.goTeams', { a: Math.ceil(n / tm), b: tm }) : t('br.goSolo', { n: n })) +
    '</button><div class="brfoot">🎟️ ' + (BR.FREE ? t('br.free') : t('br.ticket', { n: tkN })) +
      t('br.foot', { b: brBossN(), f: brFoeN() }) + '</div></div>' +
  '</div>';
}
function brSumText() {
  const o = BR.opt, n = o.n | 0, tm = o.team | 0, du = o.dur | 0;
  return tm >= 2
    ? t('brsum.teams', { a: Math.ceil(n / tm), b: tm, d: du, r: du === 5 ? 5 : 10 })
    : t('brsum.solo', { n: n, d: du, r: du === 5 ? 5 : 10, b: brBossN() });
}

/* v5.40：卡片裡的按鈕（✕／出發）與名字輸入改成「每次重畫都重新綁」。
   以前只在第一次開卡時綁一次，但「切換地圖尺寸」會讓 ov.innerHTML = brCardHTML() 整張重畫，
   #brGo / #brOk 變成全新的節點 → 舊的事件監聽全部消失 → 按「出發」完全沒反應。
   這就是「選小地圖不能開、切了地圖也不能開」的真正原因（地圖尺寸是唯一會重畫的選項）。 */
function brCardWire(ov) {
  try { CharPreview.mount(ov); } catch (e) {}
  const nmIn = $id('brName');
  if (nmIn) {
    nmIn.addEventListener('input', function () {
      settings.brName = String(nmIn.value || '').slice(0, 8);
      saveSettings();
    });
    // 打字時不要把按鍵送進遊戲（WASD 會被當成移動）
    nmIn.addEventListener('keydown', function (ev) { ev.stopPropagation(); });
  }
  const okB = $id('brOk');
  if (okB) okB.addEventListener('click', function () {
    AudioSys.sfx('click'); ov.classList.add('hide');
  });
  const goB = $id('brGo');
  if (goB) goB.addEventListener('click', function () {
    AudioSys.sfx('click');
    let tkN = 0;
    try { tkN = Shop.tickets ? Shop.tickets() : 0; } catch (e) {}
    if (!BR.FREE && tkN <= 0) {
      ov.classList.add('hide');
      try { Shop.open(); } catch (e) {}
      return;
    }
    /* v5.64：押注要在「出發當下」就扣 —— 不能等結算才扣，
       否則輸了直接關視窗就逃帳，這條出口等於不存在。 */
    Game.brBet = 0;
    const bet = Math.max(0, BR.opt.bet | 0);
    if (bet > 0) {
      let rr = null;
      try { rr = Shop.spend(bet); } catch (e) { rr = null; }
      if (rr && rr.ok) Game.brBet = bet;
      else {
        BR.opt.bet = 0;
        try { AudioSys.sfx('hurt'); } catch (e) {}
        try { toast(t('shop.noGold'), 2.2); } catch (e) {}
      }
    }
    ov.classList.add('hide');
    try { startBR(); } catch (e) { try { __bootFail('startBR', e); } catch (e2) {} }
  });
}

$id('btnBR').addEventListener('click', function () {
  AudioSys.sfx('click');
  let ov = $id('brOv');
  if (!ov) {
    ov = document.createElement('div');
    ov.id = 'brOv'; ov.className = 'overlay-in';
    document.body.appendChild(ov);
  }
  ov.innerHTML = brCardHTML();
  ov.classList.remove('hide');
  // v5.11：角色預覽（走動畫）＋ 命名輸入；v5.40 統一走 brCardWire（重畫後也要重綁）
  brCardWire(ov);
  ov.onclick = function (ev) {
    const tgt = ev.target;
    // 選角箭頭（比照對戰：◀ ▶ 切換外觀，選了會記住）
    const chBtn = (tgt && tgt.closest) ? tgt.closest('[data-chd]') : null;
    if (chBtn) {
      ev.stopPropagation();
      const d = parseInt(chBtn.getAttribute('data-chd'), 10) || 1;
      const n = CHARACTERS.length;
      settings.brChar = ((((settings.brChar | 0) + d) % n) + n) % n;
      saveSettings();
      AudioSys.sfx('click');
      const cv = ov.querySelector('.brchpv');
      if (cv) cv.setAttribute('data-ch', String(settings.brChar));
      try { CharPreview.mount(ov); CharPreview.hop(settings.brChar); } catch (e) {}
      // 沒輸入名字時，輸入框的提示字就是角色名（跟對戰的 pbox 同一個做法）
      const nm2 = $id('brName');
      if (nm2) nm2.setAttribute('placeholder', charName(CHARACTERS[settings.brChar]));
      return;
    }
    const b = ev.target;
    if (b && b.tagName === 'B' && b.dataset && b.dataset.v) {
      const k = b.parentNode.getAttribute('data-k');
      const keepZero = (k === 'map' || k === 'bet');   // v5.37：map 的 0 是「原圖」；v5.64：bet 的 0 是「不押注」——都不能被 || 1 吃掉
      BR.opt[k] = keepZero ? (parseInt(b.dataset.v, 10) || 0) : (parseInt(b.dataset.v, 10) || 1);
      AudioSys.sfx('click');
      if (k === 'map') {                        // 換尺寸 → 人數選項與上限一起換，整張卡重畫
        const bigNow = (BR.opt.map | 0) !== 0;
        BR.opt.n = Math.min(BR.opt.n | 0, bigNow ? 100 : 50);
        saveSettings();
        ov.innerHTML = brCardHTML();
        brCardWire(ov);                         // v5.40：重畫後一定要重綁，否則「出發」按不動
        return;
      }
      const on = b.parentNode.querySelectorAll('b');
      for (let i = 0; i < on.length; i++) on[i].classList.toggle('on', on[i] === b);
      const sum = $id('brSum');
      if (sum) sum.innerHTML = brSumText();
      const go = $id('brGo');
      if (go) go.textContent = (BR.opt.team | 0) >= 2
        ? ('出發（' + Math.ceil(BR.opt.n / BR.opt.team) + ' 隊 × ' + BR.opt.team + ' 人）')
        : ('出發（' + BR.opt.n + ' 人混戰）');
    }
  };
});
