/* v5.37：把這台伺服器的區網網址列出來（手機連同一個 WiFi 就能玩）。
   線上版（Render）拿到的會是容器內網 IP，對玩家沒用 → 改成文字說明。 */
function lanRefresh() {
  const box = $id('lanUrls'), tip = $id('lanTip');
  if (!box) return;
  let host = '';
  try { host = String(location.hostname || ''); } catch (e) {}
  const isLocal = host === 'localhost' || host === '127.0.0.1' || host === '[::1]' || host === '::1'
    || /^192\.168\./.test(host) || /^10\./.test(host) || /^172\.(1[6-9]|2\d|3[01])\./.test(host);
  if (location.protocol === 'file:') {
    box.innerHTML = '<span class="lanurl">file:// 開啟（沒有後端）</span>';
    if (tip) tip.textContent = '直接雙擊 index.html 沒有連線功能：請在電腦執行 node server.js，手機開 http://<電腦IP>:3000。';
    return;
  }
  if (!isLocal) {
    box.innerHTML = '<span class="lanurl">線上版（Render）</span>';
    if (tip) tip.textContent = '線上版是公開伺服器，沒有區網位址。想玩區網：在電腦執行 node server.js，手機連同一個 WiFi 後開 http://<電腦IP>:3000（本頁下方會自動列出網址）。';
    return;
  }
  box.innerHTML = '<span class="lanurl">讀取區網位址…</span>';
  fetch('/api/lan', { cache: 'no-store' }).then(function (r) { return r.json(); }).then(function (j) {
    const addrs = (j && j.addrs) || [];
    if (!addrs.length) {
      box.innerHTML = '<span class="lanurl">' + (location.origin || '') + '</span>';
    } else {
      box.innerHTML = addrs.map(function (a) {
        return '<span class="lanurl" title="' + a.name + '">' + a.url + '</span>';
      }).join('');
    }
    if (tip) tip.textContent = '手機／平板連同一個 WiFi，打開上面任一網址就能進同一個房間系統（這台電腦就是主機）。';
  }).catch(function () {
    box.innerHTML = '<span class="lanurl">' + (location.origin || '') + '</span>';
    if (tip) tip.textContent = '抓不到區網位址：確認伺服器正在執行，並允許防火牆的 3000 埠。';
  });
}
