  if (e.boss) {
    try { pushPop(e.x, e.y - (e.r || 20), '+' + g + ' EXP', { color: '#ffe27a', size: .85 }); } catch (x) {}
    try { Gift.add('rpgBoss', 1); } catch (x) {}     // v5.20：RPG 專屬每日任務「打倒魔王」
  }
  return g;
