/* ============================================================================
 * v5.5：累計遊玩時間 ＋ 拜訪紀錄（前端側）
 * ----------------------------------------------------------------------------
 * 後台的「會員 → 累計遊玩」一直顯示 0h00m，原因是前端從來沒有把時間送給後端
 * （舊版只有 stage-clear 帶 playSec，而那個值又只做 Math.max → 幾乎永遠是 0）。
 * 這裡的做法：
 *   · 每幀只看 Game.state === 'play'（倒數／暫停／選單都不算），累加到本機
 *   · 每 60 秒把「還沒回報的秒數」POST /api/rpg/play；關頁／切背景再補一次
 *   · 離線（沒 session、或 GitHub Pages 靜態站）就留在本機，等有 session 再補
 *   · 另外每次開啟頁面 ping 一次 /api/visit（後台「歷史／今日拜訪人數」）
 * ========================================================================== */
const PlayStat = (function () {
  const K_LOCAL = 'bombhero-playsec';        // 這台裝置累計玩了幾秒
  const K_SENT = 'bombhero-playsec-sent';    // 其中已經回報給伺服器幾秒
  const MODES = { solo: 1, rpg: 1, battle: 1, br: 1 };
  const FLUSH_EVERY = 60000;                 // 60 秒回報一次
  const MAX_PER_POST = 7200;                 // 單次上限 2 小時（後端也有一樣的夾制）
  let local = 0, sent = 0, sinceSave = 0, busy = false, booted = false;
  function num(k) {
    try { const v = parseInt(localStorage.getItem(k) || '0', 10); return (isFinite(v) && v > 0) ? v : 0; }
    catch (e) { return 0; }
  }
  function load() { local = num(K_LOCAL); sent = Math.min(num(K_SENT), local); }
  function save() {
    try {
      localStorage.setItem(K_LOCAL, String(local | 0));
      localStorage.setItem(K_SENT, String(sent | 0));
    } catch (e) {}
  }
  function cloudOnline() {
    try {
      const C = (typeof window !== 'undefined' && window.__BH && window.__BH.Cloud) || null;
      return !!(C && C.online && C.online());
    } catch (e) { return false; }
  }
  function modeOk(m) { return !!MODES[m]; }
  /* 每幀呼叫：只有「真的在玩」才累加 */
  function tick(dt) {
    if (!(dt > 0) || dt > .5) return;
    if (Game.state !== 'play') return;
    if (!modeOk(Game.mode)) return;
    local += dt;
    sinceSave += dt;
    if (sinceSave >= 10) { sinceSave = 0; save(); }
  }
  function pending() { return Math.max(0, Math.floor(local - sent)); }
  function flush(force) {
    const n = pending();
    if (busy || n < (force ? 1 : 5)) return Promise.resolve(false);
    if (typeof fetch !== 'function') return Promise.resolve(false);
    if (!cloudOnline()) return Promise.resolve(false);   // 沒 session 先留在本機，下次再補
    const sec = Math.min(MAX_PER_POST, n);
    busy = true;
    return fetch(apiPath('/api/rpg/play'), {
      method: 'POST', credentials: 'same-origin', keepalive: true,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ sec: sec })
    }).then(function (r) { return r.json(); }).then(function (j) {
      busy = false;
      if (j && j.ok) { sent += sec; save(); return true; }
      return false;
    }, function () { busy = false; return false; });
  }
  /* 拜訪紀錄：Pages（跨網域）時打 Render 的絕對網址，同源就直接用相對路徑 */
  function visitUrl() {
    try {
      const o = (typeof Lb !== 'undefined' && Lb.origin) ? Lb.origin() : '';
      if (o) return o + '/api/visit';
    } catch (e) {}
    return apiPath('/api/visit');
  }
  function ping() {
    if (typeof fetch !== 'function') return;
    let dev = '';
    try { dev = (typeof Lb !== 'undefined' && Lb.deviceId) ? Lb.deviceId() : ''; } catch (e) { dev = ''; }
    if (!dev || dev.length < 6) return;
    try {
      fetch(visitUrl(), {
        method: 'POST', credentials: 'omit', keepalive: true,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ deviceId: dev, v: (typeof VERSION !== 'undefined' ? VERSION : '') })
      }).then(function (r) { return r.json(); }).then(function (j) {
        if (j && j.ok) { try { window.__BHVISIT = j; } catch (e) {} }
      }, function () {});
    } catch (e) {}
  }
  function boot() {
    if (booted) return;
    booted = true;
    load();
    try { if (typeof setInterval === 'function') setInterval(function () { flush(false); }, FLUSH_EVERY); } catch (e) {}
    try {
      window.addEventListener('pagehide', function () { save(); flush(true); });
      document.addEventListener('visibilitychange', function () {
        if (document.visibilityState === 'hidden') { save(); flush(true); }
      });
    } catch (e) {}
    try { setTimeout(ping, 1500); } catch (e) {}
  }
  return {
    boot: boot, tick: tick, flush: flush, ping: ping, pending: pending,
    state: function () { return { local: local | 0, sent: sent | 0, pending: pending(), busy: busy }; },
    _reset: function () { local = 0; sent = 0; sinceSave = 0; save(); },
    _load: load, _save: save, FLUSH_EVERY: FLUSH_EVERY, MAX_PER_POST: MAX_PER_POST
  };
})();

/* ============================================================================
   v5.76：Escape 關掉「最上層的面板」
   ─────────────────────────────────────────────────────────────────────────
   問題（實際巡檢抓到）：
     · 圖鑑／成就／排名／線上玩家／版本面板／外觀收藏 <b>全部不吃 Escape</b>，
       桌機玩家按 Escape 一點反應都沒有，只能去摸右上角那顆小叉。
     · 更嚴重的是「面板沒關就直接開遊戲」——外觀收藏是 position:fixed 全螢幕，
       它會整片蓋在戰場上，玩家看不到自己在哪（截圖確認過）。
   做法：
     · 一個捕獲階段的全域監聽：有面板開著時 Escape 只關面板，並且吞掉事件，
       不要讓下面的「ESC 開暫停」也一起觸發。
     · 進遊戲（Screen.apply('game')）時把還開著的面板全部關掉。
   ========================================================================== */
function bhDialogVisible(el) {
  if (!el || !el.getClientRects) return false;
  if (!el.getClientRects().length) return false;
  const cs = getComputedStyle(el);
  if (cs.display === 'none' || cs.visibility === 'hidden' || parseFloat(cs.opacity) < .05) return false;
  return true;
}
const BH_DIALOG_IDS = ['codexModal', 'achModal', 'rankModal', 'onModal', 'avModal',
  'multiPick', 'giftPanel', 'verLog', 'skinPanel', 'gateOv'];
function bhOpenDialogs() {
  const out = [];
  BH_DIALOG_IDS.forEach(function (id) {
    const el = document.getElementById(id);
    if (!bhDialogVisible(el)) return;
    const z = parseInt(getComputedStyle(el).zIndex, 10);
    out.push({ el: el, id: id, z: isNaN(z) ? 0 : z });
  });
  // z-index 大的在上面；同層就照 DOM 順序（後面的在上面）
  out.sort(function (a, b) {
    if (a.z !== b.z) return a.z - b.z;
    return (a.el.compareDocumentPosition(b.el) & 4) ? -1 : 1;
  });
  return out;
}
function bhCloseDialog(box) {
  if (!box) return false;
  const btn = box.querySelector('.skclose, [id$="X"], [id$="Close"], [data-close]');
  if (btn) { try { btn.click(); return true; } catch (e) { return false; } }
  return false;
}
function closeTopDialog() {
  const list = bhOpenDialogs();
  if (!list.length) return false;
  return bhCloseDialog(list[list.length - 1].el);
}
function closeAllDialogs() {
  let n = 0;
  const done = {};
  for (let i = 0; i < 6; i++) {
    const list = bhOpenDialogs().filter(function (d) { return !done[d.id]; });
    if (!list.length) break;
    const top = list[list.length - 1];
    done[top.id] = 1;
    if (!bhCloseDialog(top.el)) break;
    n++;
  }
  return n;
}
window.addEventListener('keydown', function (e) {
  if (e.key !== 'Escape' && e.code !== 'Escape') return;
  if (!bhOpenDialogs().length) return;      // 沒開面板 → 交給原本的 ESC（開暫停）
  closeTopDialog();
  try { Input.edges.Escape = false; } catch (e2) {}   // 不要順便開暫停
  try { e.preventDefault(); } catch (e3) {}
  try { e.stopPropagation(); } catch (e4) {}
}, true);

